/* Server-backed Node.js adapter. /demo retains the separate fictional prototype. */
let sessionUser=null,csrfToken=null,serverDrivers=[],pendingAction=false,authFlow='login',pendingCredentials=null,resetToken=new URLSearchParams(location.search).get('token')||'';
/* actualRole and impersonating are declared by app.js, which loads first; only reset them here. */
actualRole=null;impersonating=false;
shipments=[];activity=[];fleet=[];let liveSocket=null,liveRefresh=false;
async function api(path,{method='GET',body}={}){let response=await fetch(path,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'&&csrfToken?{'X-CSRF-Token':csrfToken}:{})},body:body?JSON.stringify(body):undefined});let value=await response.json();if(!response.ok){let error=new Error(value.error||'Request failed');error.status=response.status;error.code=value.code;throw error;}return value;}
function fail(error){if(error.status===401){sessionUser=null;csrfToken=null;auth();}toast(error.message||'Cannot connect to the server. Your changes were not saved.');}
function connectLiveUpdates(){if(!sessionUser||!window.io)return;if(!liveSocket){liveSocket=window.io({withCredentials:true});liveSocket.on('connect',()=>shipments.forEach(s=>liveSocket.emit('join:shipment',s.id)));liveSocket.on('shipment:update',async()=>{if(liveRefresh)return;liveRefresh=true;try{await loadState();render()}catch{}finally{liveRefresh=false}});liveSocket.on('gps:update',()=>{document.dispatchEvent(new Event('yyc:gps-update'));loadAdminTracking();loadTrackingCards()});}else if(liveSocket.connected)shipments.forEach(s=>liveSocket.emit('join:shipment',s.id));}
async function loadState(){let state=await api('/api/state');sessionUser=state.user;actualRole=sessionUser.role;if(!impersonating)role=actualRole;shipments=state.shipments;serverDrivers=state.drivers;storeProfile={...sessionUser.profile,name:sessionUser.name,email:sessionUser.email};let ownTruck=sessionUser.truck;driverProfile=role==='driver'?{...ownTruck,name:sessionUser.name,email:sessionUser.email,approved:sessionUser.approved&&ownTruck?.approved,documents:[]}:{name:'Selected assigned driver',type:'Box truck',kg:0,pallets:0,approved:false,documents:[]};activity=shipments.flatMap(s=>s.history||[]).sort((a,b)=>b.time.localeCompare(a.time)).map(e=>e.actor+' · '+e.text);if(!activity.length)activity=['No delivery activity yet.'];connectLiveUpdates();}
async function boot(){page='loading';if(resetToken)authFlow='reset';$('#root').innerHTML='<main class="authloading">'+logo()+'<p>Loading your YYC workspace…</p></main>';try{let s=await api('/api/session');csrfToken=s.csrf;if(!s.user){auth();return}await loadState();page=role==='admin'?'dispatch':role==='driver'?'ontrip':'dashboard';render();}catch(e){$('#root').innerHTML='<main class="authloading">'+logo()+'<h2>Cannot load YYC</h2><p>'+E(e.message)+'</p><button class="btn" onclick="boot()">Retry</button></main>';}}
auth=function(){page='auth';closeDrawer();let register=authMode==='register';let verification=authFlow==='verify',resetting=authFlow==='reset',requestingReset=authFlow==='request-reset',mfaStep=authFlow==='mfa';$('#root').innerHTML=`<div class="auth"><section class="hero">${logo()}<div><div class="eyebrow">YYC BROKERS</div><h1>Your goods.<br>Your drivers.<br><span>One workspace.</span></h1><p>Manage transport requests, quotations, assignments and delivery evidence in your YYC workspace.</p>${truckArt}</div><div class="herofoot"><span>Request</span><span>Assign</span><span>Deliver</span></div></section><section class="authright"><header><span>YYC NODE.JS STARTER</span><a href="/demo/" class="textbtn">Open screen demo →</a></header><div class="authbox"><div class="eyebrow muted">${register?'JOIN THE NETWORK':verification?'VERIFY EMAIL':resetting||requestingReset?'RESET PASSWORD':mfaStep?'TWO STEP SIGN IN':'WELCOME BACK'}</div><h1>${register?'Create your YYC account.':verification?'Verify your email address.':resetting?'Choose a new password.':requestingReset?'Request a reset link.':mfaStep?'Enter your authenticator code.':'Log in to your workspace.'}</h1><p class="muted">${register?'Driver accounts require broker approval before accepting jobs.':verification?'Enter the code sent to your email.':resetting?'Use at least 12 characters.':requestingReset?'We will email a link if the account exists.':mfaStep?'Use an authenticator code or backup code.':'Store owners, drivers and brokers use their own email and password.'}</p><div class="switch" style="margin-top:24px"><button class="${!register?'selected':''}" onclick="setAuth('login')">Log in</button><button class="${register?'selected':''}" onclick="setAuth('register')">Register</button></div>${register?`<div class="roles">${['store','driver','admin'].map(r=>`<button type="button" class="role ${r===authRole?'selected':''}" onclick="chooseAuth('${r}')">${icon(r==='store'?'store':r==='driver'?'truck':'grid')}<b>${r==='store'?'Store owner':r==='driver'?'Driver / truck owner':'YYC Broker'}</b></button>`).join('')}</div>`:''}<form id="realAuth" onsubmit="${register?'registerStep':verification?'verifyEmail':resetting?'resetPassword':requestingReset?'sendResetRequest':'login'}(event)">${register?`<div class="grid2">${field('name',authRole==='store'?'Store / business name':'Full name')}${field('phone','Contact phone','tel')}</div>`:''}${(!mfaStep&&!resetting)?field('email','Email address','email','you@example.com'):''}${register||resetting?field('password',register?'Password':'New password','password','12 to 128 characters'):''}${register?field('confirm','Confirm password','password'):''}${verification?field('code','Verification code','text','6 digit code'):''}${mfaStep?field('mfaCode','Authenticator or backup code','text'):''}${resetting?field('confirm','Confirm new password','password'):''}${!register&&!verification&&!resetting&&!requestingReset&&!mfaStep?field('password','Password','password','12 to 128 characters'):''}${register&&authRole==='store'?field('address','Store delivery address')+field('contact','Receiving contact'):''}${register&&authRole==='admin'?field('brokerCode','Broker registration code','text','Contact YYC for code'):''}${register&&authRole==='driver'?`<h2 style="margin:24px 0">Register your truck</h2><div class="grid2">${field('truck','Truck make and model')}${field('plate','Plate / unit reference')}${select('type','Truck type',['Box truck','Dry van'])}${field('kg','Payload capacity (kg)','number')}${field('pallets','Pallet capacity','number')}${field('area','Service area')}</div><label class="checkrow"><input type="checkbox" name="liftgate">Truck has a liftgate</label>`:''}<p id="authError" class="error" role="alert"></p><button class="btn" style="width:100%;margin-top:18px">${register?'Create account':verification?'Verify email':resetting?'Reset password':requestingReset?'Send reset link':mfaStep?'Verify code':'Log in'} ${icon('arrow')}</button></form>${!register&&!verification&&!resetting&&!requestingReset&&!mfaStep?'<div class="row between wrap" style="margin-top:12px"><button class="textbtn" type="button" onclick="authFlow=\'verify\';auth()">Verify email</button><button class="textbtn" type="button" onclick="requestReset()">Forgot password?</button></div>':''}${mfaStep?'<button class="textbtn" type="button" onclick="authFlow=\'login\';auth()">Back to login</button>':''}<div class="notice">Use your account email to complete verification and password recovery.</div></div></section></div>`;document.querySelectorAll('#realAuth input[type=password]').forEach(i=>{i.minLength=12;i.maxLength=128;i.autocomplete=register?'new-password':'current-password'});$('#email').autocomplete='username';};
setAuth=function(m){authMode=m;auth()};chooseAuth=function(r){authRole=r;auth()};
login=async function(e){e.preventDefault();let button=e.target.querySelector('button[type=submit]')||e.target.querySelector('button:last-child');button.disabled=true;let data=authFlow==='mfa'?{...pendingCredentials,mfaCode:Object.fromEntries(new FormData(e.target)).mfaCode}:Object.fromEntries(new FormData(e.target));try{let result=await api('/api/login',{method:'POST',body:data});if(result.mfaRequired){pendingCredentials={email:data.email,password:data.password};authFlow='mfa';auth();return;}csrfToken=result.csrf;e.target.reset();await loadState();page=role==='admin'?'dispatch':role==='driver'?'ontrip':'dashboard';render();}catch(error){$('#authError').textContent=error.message;button.disabled=false;}};
verifyEmail=async function(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));try{await api('/api/verify-email',{method:'POST',body:d});authFlow='login';auth();toast('Email verified. You can now sign in.')}catch(x){$('#authError').textContent=x.message}};
sendResetRequest=async function(e){e.preventDefault();let {email}=Object.fromEntries(new FormData(e.target));try{await api('/api/request-reset',{method:'POST',body:{email}});authFlow='login';auth();toast('If that account exists, a reset link was sent.')}catch(x){$('#authError').textContent=x.message}};
requestReset=function(){authFlow='request-reset';auth()};
resetPassword=async function(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.password!==d.confirm){$('#authError').textContent='Passwords do not match.';return}try{await api('/api/reset-password',{method:'POST',body:{token:resetToken,password:d.password}});resetToken='';authFlow='login';auth();toast('Password reset. Please sign in.')}catch(x){$('#authError').textContent=x.message}};
registerStep=async function(e){e.preventDefault();let form=e.target,data=Object.fromEntries(new FormData(form));if(data.password!==data.confirm){$('#authError').textContent='Passwords must match.';return}let button=form.querySelector('button:last-child');button.disabled=true;data.role=authRole;data.liftgate=!!data.liftgate;if(authRole==='driver'){data.kg=Number(data.kg);data.pallets=Number(data.pallets);}delete data.confirm;try{await api('/api/register',{method:'POST',body:data});let email=data.email;form.reset();authMode='login';authFlow='verify';auth();let input=document.querySelector('#email');if(input)input.value=email;toast('Account created. Enter the verification code emailed to you.');}catch(error){$('#authError').textContent=error.message;button.disabled=false;}};
async function beginMfaEnrollment(){try{let d=await api('/api/mfa/enroll',{method:'POST',body:{}});$('#overlay').innerHTML='<section class="card"><h2>Set up authenticator</h2><img alt="Authenticator QR code" src="'+d.qrCode+'" style="max-width:220px"><p>Manual key: '+E(d.secret)+'</p><form onsubmit="finishMfaEnrollment(event)"><input name="code" inputmode="numeric" required placeholder="6 digit code"><button class="btn">Confirm</button></form></section>';}catch(e){fail(e)}}
async function uploadComplianceDocument(e){e.preventDefault();let form=e.target,file=form.elements.file.files[0],type=form.elements.documentType.value;try{if(file.size>12*1024*1024)throw new Error('Choose a file smaller than 12 MB');let ext=file.name.split('.').pop().toLowerCase();if(!['pdf','jpg','jpeg','png'].includes(ext))throw new Error('Choose a PDF, JPG or PNG file');let signed=await api('/api/documents/upload-url',{method:'POST',body:{documentType:type,fileExtension:ext}});let put=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!put.ok)throw new Error('File upload failed');await api('/api/documents',{method:'POST',body:{s3Key:signed.s3Key,filename:file.name,documentType:type,fileSize:file.size,contentType:file.type,expiryDate:form.elements.expiryDate.value||null}});toast('Document uploaded for review');form.reset();await loadComplianceDocuments()}catch(x){toast(x.message)}}
async function loadComplianceDocuments(){let el=document.querySelector('#myDocuments');if(!el)return;try{let d=await api('/api/documents');el.innerHTML=d.documents.map(x=>'<div class="docitem"><div><b>'+E(x.type)+' · '+E(x.filename)+'</b><small>'+E(x.status)+(x.expiry_date?' · expires '+E(x.expiry_date):'')+'</small></div></div>').join('')||'No documents uploaded yet.'}catch(x){el.textContent=x.message}}
async function finishMfaEnrollment(e){e.preventDefault();try{let d=await api('/api/mfa/enroll/verify',{method:'POST',body:Object.fromEntries(new FormData(e.target))});alert('Save these backup codes securely: '+d.backupCodes.join(', '));closeDrawer();toast('Authenticator enabled')}catch(x){toast(x.message)}}
async function logoutAccount(){try{await api('/api/logout',{method:'POST',body:{}});liveSocket?.disconnect();liveSocket=null;mfaGate=false;sessionUser=null;csrfToken=null;shipments=[];authMode='login';auth();}catch(e){fail(e)}}
// Reuse presentation components while removing all prototype role switching.
const starterRender=render;
render=function(){if(!sessionUser){auth();return}starterRender();if(page==='booking'&&bookingStep===3){let f=document.querySelector('.wizard form');if(f&&!f.elements.stops){let wrap=document.createElement('div');wrap.className='field';wrap.innerHTML='<label for="multiStops">Optional intermediate stops</label><textarea id="multiStops" name="stops" rows=3 placeholder="address | receiving contact | time window | service minutes (one stop per line, max 8)"></textarea><small>Pickup and final destination are entered above.</small>';let foot=f.querySelector('.wizardfoot');if(foot)foot.before(wrap);}}if(page==='profile'&&role==='driver')queueMicrotask(loadComplianceDocuments);let avatar=$('.main .top .avatar');if(avatar)avatar.textContent=sessionUser.name.slice(0,2).toUpperCase();if(page==='booking'){for(let id of ['customer','email']){let f=document.getElementById(id);if(f)f.readOnly=true;}}document.querySelector('.rolepicker')?.remove();document.querySelector('.commandbar')?.remove();let identity=$('.main .top .accountname');if(identity)identity.textContent=sessionUser.name;let button=$('.sidebottom button');if(button){button.textContent='Log out';button.onclick=logoutAccount;}let footer=$('.footnote');if(footer)footer.textContent='YYC Node.js starter · Account and shipment data saved on this server · Maps, GPS, uploads and email not connected';let side=$('.sidebottom');if(side){side.innerHTML='<b>YYC Brokers</b><br>Node.js workspace<br><button class="textbtn" style="color:#d8c59e;padding:15px 0 0" onclick="logoutAccount()">Log out</button>';}let top=$('.main .top .row');if(top&&!top.querySelector('.serverrefresh')){let b=document.createElement('button');b.className='btn light small serverrefresh';b.textContent='Refresh';b.onclick=async()=>{try{await loadState();render();toast('Workspace refreshed')}catch(e){fail(e)}};top.prepend(b);}if(actualRole==='admin'&&top&&!top.querySelector('.adminimpersonate')){let picker=document.createElement('div');picker.className='rolepicker adminimpersonate';picker.innerHTML=`<span>${impersonating?'VIEWING AS':'YOUR ROLE'}</span><select aria-label="Admin impersonation" onchange="${impersonating?'this.value===\'admin\'?stopImpersonating():impersonate(this.value)':'impersonate(this.value)'}">${impersonating?'':'<option value="admin" selected>Broker</option>'}${['store','driver','admin'].map(r=>`<option value="${r}" ${r===role?'selected':''}>${({store:'Store owner',driver:'Driver',admin:'Broker'})[r]}</option>`).join('')}</select>`;top.insertBefore(picker,top.firstChild);if(impersonating){let badge=document.createElement('span');badge.className='tag amber';badge.style.marginRight='10px';badge.textContent='PREVIEW MODE';top.insertBefore(badge,top.querySelector('.serverrefresh'));}}};
const renderWithScheduleInputs=render;render=function(){renderWithScheduleInputs();if(page==='booking'&&bookingStep===3){let f=document.querySelector('.wizard form');if(f&&!f.elements.pickupServiceMinutes){let box=document.createElement('div');box.className='grid2';box.innerHTML='<div class="field"><label>Pickup loading minutes</label><input type="number" min="0" max="480" name="pickupServiceMinutes" value="30"></div><div class="field"><label>Final delivery service minutes</label><input type="number" min="0" max="480" name="deliveryServiceMinutes" value="30"></div>';let foot=f.querySelector('.wizardfoot');if(foot)foot.before(box);}}};
switchRole=function(){if(actualRole==='admin')stopImpersonating();else toast('Your account role is enforced by the server. Log out to use another account.')};function impersonate(r){if(actualRole!=='admin')return;role=r;impersonating=true;page='dashboard';filter='';query='';render();toast('Previewing '+({admin:'Broker',store:'Store owner',driver:'Driver'})[r]+' view')}function stopImpersonating(){if(actualRole!=='admin')return;role=actualRole;impersonating=false;page=actualRole==='admin'?'dispatch':'dashboard';filter='';query='';render();toast('Returned to Broker view')}enterDemo=function(){auth()};own=function(){return role==='driver'?shipments.filter(s=>s.driverId===sessionUser.id):shipments;};
function driverLabel(s){return s.driverName||'Not assigned'}
function noMap(){return `<div class="unconnectedmap"><span class="unconnectedicon">${icon('route')}</span><h2>Google Maps is not connected.</h2><p>No live vehicle position or GPS data is collected.<br>Delivery status is recorded by the assigned driver.</p><span class="tag gray">MAPS / GPS SETUP REQUIRED</span></div>`}
mapGraphic=function(){return noMap()};
const starterContent=content;
content=function(){if(role==='admin'&&page==='dispatch')return realDispatch();if(role==='admin'&&page==='approvals')return realApprovals();if(role==='admin'&&page==='alerts')return realAlerts();if(page==='schedule')return title('Delivery work board','Current server records grouped by shipment state.')+`<div class="card">${table(shipments)}</div>`;if(role==='store'&&page==='dashboard')return realStoreHome();if(role==='store'&&page==='tracking')return realStoreTracking();if(role==='driver'&&['ontrip','dashboard'].includes(page))return realDriver();if(role==='driver'&&page==='offers')return realOffers();if(page==='profile')return realProfile();return starterContent();};
const profileBeforePreferences=realProfile;realProfile=function(){let html=profileBeforePreferences();queueMicrotask(loadComplianceDocuments);queueMicrotask(loadNotificationPreferences);return html+'<section class="card" style="margin-top:20px"><h2>Notification preferences</h2><form id="notificationPreferences" onsubmit="saveNotificationPreferences(event)"><label><input type="checkbox" name="email" checked>Email</label><label><input type="checkbox" name="sms">SMS</label><label><input type="checkbox" name="push" checked>Push</label><button class="btn light">Save preferences</button></form></section>'};async function loadNotificationPreferences(){let f=document.querySelector('#notificationPreferences');if(!f)return;try{let {preferences:p}=await api('/api/notifications/preferences');for(let k of ['email','sms','push'])f.elements[k].checked=p[k]===true}catch{}}async function saveNotificationPreferences(e){e.preventDefault();let f=e.target;try{await api('/api/notifications/preferences',{method:'PATCH',body:Object.fromEntries(['email','sms','push'].map(k=>[k,f.elements[k].checked]))});toast('Notification preferences saved')}catch(x){toast(x.message)}}
function realDispatch(){let pending=shipments.filter(s=>['Awaiting quote','Ready to assign'].includes(s.status));queueMicrotask(loadAdminTracking);return title('Every truck. Every delivery.','Requests, approvals and the next operational action.',`<button class="btn" onclick="nav('shipments')">Review deliveries →</button>`)+stats([['Active deliveries','Server records',shipments.filter(s=>!['Delivered','Cancelled'].includes(s.status)).length,'truck'],['Awaiting quote','Needs a quotation',shipments.filter(s=>s.status==='Awaiting quote').length,'clock'],['Driver approvals','Pending review',serverDrivers.filter(d=>!d.approved||!d.truck?.approved).length,'user'],['Delivered','Evidence recorded',shipments.filter(s=>s.status==='Delivered').length,'check']])+`<div class="layout"><section class="card"><div class="row between"><h2>Delivery board</h2><button class="textbtn" onclick="nav('shipments')">View all →</button></div>${table(shipments)}</section><div><section class="card action"><span class="eyebrow">OPERATIONS DESK</span><h2 style="margin-top:15px">${pending.length} requests need attention.</h2><p>Review quotations and offer suitable jobs to approved drivers.</p><button class="btn gold" onclick="nav('alerts')">Open work queue →</button></section><section class="card" style="margin-top:20px"><h2>Driver network</h2>${serverDrivers.length?serverDrivers.map(d=>`<div class="casecontact"><b>${E(d.name)}</b>${E(d.truck?.truck||'No truck')} · ${E(d.truck?.plate||'')}<br>${badge(d.approved&&d.truck?.approved?'Approved':'Pending review')}</div>`).join(''):'<p class="muted" style="margin-top:15px">No driver registrations yet.</p>'}</section></div></div><section class="card" style="margin-top:22px"><h2>Active driver locations</h2><div id="adminTracking">Loading live locations…</div></section>`;}

document.addEventListener('yyc:gps-update',()=>{loadTrackingCards();loadAdminTracking()});
async function loadAdminTracking(){let el=document.querySelector('#adminTracking');if(!el)return;try{let {locations}=await api('/api/admin/gps/active');el.innerHTML=locations.map(x=>{let lat=Number(x.latitude),lng=Number(x.longitude);return `<div class="card"><b>${E(x.shipment_id)} · ${E(x.shipment_status)}</b><p>${new Date(x.recorded_at).toLocaleTimeString()}</p><a target="_blank" rel="noopener" href="https://maps.google.com/?q=${lat},${lng}">Open in Maps</a><iframe title="${E(x.shipment_id)} live location" width="100%" height="220" loading="lazy" style="border:0" src="https://www.google.com/maps?q=${lat},${lng}&output=embed"></iframe></div>`}).join('')||'No active location reports.'}catch(e){el.textContent=e.message}}
const dispatchBeforeProviderUI=realDispatch;realDispatch=function(){return dispatchBeforeProviderUI().replace('<div id="adminTracking">','<button class="btn light" onclick="verifyProviders()">Verify connected services</button><div id="providerResults"></div><div id="adminTracking">')};
async function verifyProviders(){let el=document.querySelector('#providerResults');if(el)el.textContent='Checking service connections…';try{let {providers,checkedAt}=await api('/api/admin/providers/verify',{method:'POST',body:{}});if(el)el.innerHTML='<p>Checked '+E(new Date(checkedAt).toLocaleString())+'</p>'+Object.entries(providers).map(([k,v])=>'<div class="activity"><b>'+E(k)+'</b> · '+E(v.status)+(v.error?' · '+E(v.error):'')+'</div>').join('')}catch(e){if(el)el.textContent=e.message}}
function realApprovals(){queueMicrotask(loadAdminAccounts);return title('Broker operations','Review drivers, documents, and account access.')+`<div class="grid2">${serverDrivers.length?serverDrivers.map(d=>`<section class="card">${badge(d.approved&&d.truck?.approved?'Approved':'Pending review')}<h2 style="margin-top:17px">${E(d.name)}</h2><p class="muted" style="margin:13px 0">${E(d.email)} · ${E(d.profile.phone)}<br>${E(d.truck?.truck)} · ${E(d.truck?.plate)}<br>${E(d.truck?.type)} · ${E(d.truck?.kg)} kg · ${E(d.truck?.pallets)} pallets<br>${E(d.truck?.area)}</p><button class="btn" style="margin-top:18px" ${d.approved&&d.truck?.approved?'disabled':''} onclick="approveAccount('${d.id}')">Record manual approval</button></section>`).join(''):'<div class="card empty full">No driver registrations yet.</div>'}</div><section class="card" style="margin-top:22px"><h2>Uploaded documents awaiting review</h2><div id="pendingDocuments">Loading…</div></section><section class="card" style="margin-top:22px"><h2>Account access</h2><div id="adminAccounts">Loading…</div></section>`;}
async function loadAdminAccounts(){try{let [a,d]=await Promise.all([api('/api/admin/accounts'),api('/api/admin/documents/pending')]);let el=document.querySelector('#adminAccounts'),docs=document.querySelector('#pendingDocuments');if(el)el.innerHTML=a.accounts.map(x=>`<div class="activity"><span><b>${E(x.name)}</b> · ${E(x.email)} · ${E(x.role)} · ${x.email_verified?'Verified':'Unverified'} · ${x.disabled?'Suspended':'Active'}</span>${x.role!=='admin'?`<button class="btn light small" onclick="changeAccount('${x.id}',${x.disabled?'false':'true'})">${x.disabled?'Restore':'Suspend'}</button>`:''}</div>`).join('')||'No accounts';if(docs)docs.innerHTML=d.documents.map(x=>`<div class="activity"><span>${E(x.filename)} · ${E(x.type)} · ${E(x.status)} · expires ${E(x.expiry_date||'not set')}</span><button class="btn light small" onclick="reviewDocument('${x.id}','approve')">Approve</button><button class="btn light small" onclick="reviewDocument('${x.id}','reject')">Reject</button></div>`).join('')||'No pending uploads'}catch(e){let el=document.querySelector('#adminAccounts');if(el)el.textContent=e.message}}
async function changeAccount(id,suspend){try{await api(`/api/admin/accounts/${id}/${suspend?'suspend':'restore'}`,{method:'POST',body:{}});await loadAdminAccounts()}catch(e){toast(e.message)}}
async function reviewDocument(id,decision){let notes=decision==='reject'?prompt('Reason for rejection'):'';if(decision==='reject'&&!notes)return;try{await api(`/api/admin/documents/${id}/${decision}`,{method:'POST',body:{notes}});await loadAdminAccounts()}catch(e){toast(e.message)}}
async function approveAccount(id){try{await api('/api/drivers/'+id+'/approve',{method:'POST',body:{}});await loadState();render();toast('Driver and truck approval recorded')}catch(e){fail(e)}}
function dispatchExpired(s){return s.status==='Quote ready'&&s.quoteExpiresAt&&Date.parse(s.quoteExpiresAt)<=Date.now()||s.status==='Offered'&&s.offerExpiresAt&&Date.parse(s.offerExpiresAt)<=Date.now()}function realAlerts(){let list=shipments.filter(s=>s.issue&&!s.issue.resolved||['Awaiting quote','Ready to assign'].includes(s.status)||dispatchExpired(s));return title('Operations work queue','Unresolved exceptions and deliveries waiting for a decision.')+`<div class="grid2">${list.length?list.map(s=>`<section class="card"><span class="tag amber">${s.issue&&!s.issue.resolved?'OPEN EXCEPTION':E(s.status)}</span><h2 style="margin-top:15px">${s.id} · ${E(s.customer)}</h2><p class="muted" style="margin:15px 0">${E(s.issue&&!s.issue.resolved?s.issue.reason:s.destination)}</p>${dispatchExpired(s)?`<button class="btn light" onclick="action('${s.id}','${s.status==='Offered'?'expireOffer':'expireQuote'}')">Close expired ${s.status==='Offered'?'offer':'quote'}</button>`:`<button class="btn light" onclick="openDelivery('${s.id}')">Review delivery →</button>`}</section>`).join(''):'<div class="card empty full">No shipment actions waiting.</div>'}</div>`;}
function realStoreHome(){return title('Your deliveries. Your next move.','Request transport and follow your own shipments.',`<button class="btn" onclick="nav('booking')">＋ Request delivery</button>`)+stats([['My deliveries','Saved requests',shipments.length,'box'],['Quotes to review','Waiting for your response',shipments.filter(s=>s.status==='Quote ready').length,'file'],['In transit','Goods picked up',shipments.filter(s=>s.status==='In transit').length,'truck'],['Delivered','Evidence recorded',shipments.filter(s=>s.status==='Delivered').length,'check']])+`<section class="card"><h2>My delivery requests</h2>${table(shipments)}</section><div class="notice">Your delivery status is stored on the server. Live truck location and ETA require the separate Google Maps / phone GPS integration.</div>`;}
function realStoreTracking(){let list=shipments.filter(s=>s.driver&&!['Delivered','Cancelled'].includes(s.status));queueMicrotask(loadTrackingCards);return title('Delivery progress','Live driver position and route estimate when location sharing is enabled.')+`<div class="grid2">${list.length?list.map(s=>`<section class="card"><div class="row between"><h2>${s.id}</h2>${badge(s.status)}</div>${route(s)}<p class="muted">Assigned driver: ${E(driverLabel(s))}</p>${journeyProgress(s)}<div id="tracking-${s.id}" class="notice">Waiting for driver location…</div><button class="btn light" onclick="openDelivery('${s.id}')">View delivery details</button></section>`).join(''):'<section class="card empty full">No active assigned delivery to track.</section>'}</div>`;}
async function loadTrackingCards(){for(const s of shipments.filter(x=>x.driver&&!['Delivered','Cancelled'].includes(x.status))){let el=document.getElementById('tracking-'+s.id);if(!el)continue;try{let {location:l}=await api('/api/shipments/'+s.id+'/location');if(!l){el.textContent='No driver location yet. Driver must enable location sharing.';continue}const lat=Number(l.latitude),lng=Number(l.longitude),waypoints=[...(s.stops||[]).map(x=>x.address||x),s.destination].join(' to:');el.innerHTML='Last location: '+new Date(l.recorded_at).toLocaleTimeString()+' · accuracy '+Math.round(Number(l.accuracy)||0)+'m · <a target="_blank" rel="noopener" href="https://maps.google.com/?q='+lat+','+lng+'">Open map</a><iframe title="Live driver and route map" width="100%" height="260" loading="lazy" style="border:0;margin-top:12px" src="https://www.google.com/maps?output=embed&saddr='+lat+','+lng+'&daddr='+encodeURIComponent(waypoints)+'"></iframe>';try{let points=[...(s.stops||[]).map(x=>x.address||x),s.destination],origin={lat,lng},seconds=0;for(let destination of points){let leg=await api('/api/maps/eta',{method:'POST',body:{origin,destination}});seconds+=leg.durationInTraffic?.seconds||leg.duration?.seconds||0;origin=destination}el.innerHTML+=' · Route ETA '+E(new Date(Date.now()+seconds*1000).toLocaleString())}catch{el.innerHTML+=' · ETA unavailable (Maps is not configured)'}}catch(e){el.textContent=e.message}}}
function realDriver(){let jobs=own().filter(s=>!['Delivered','Cancelled'].includes(s.status)),offers=shipments.filter(s=>s.status==='Offered'&&s.offeredTo===sessionUser.id);return title('Your driver workspace','Your approved truck, assigned job and next action.')+(!driverProfile.approved?'<div class="alertbadge">Your driver and truck registration is pending broker review. You cannot accept jobs until approved.</div>':'')+`<div class="layout"><div>${jobs.length?jobs.map(s=>`<section class="card" style="margin-bottom:18px"><div class="row between"><h2>${s.id}</h2>${badge(s.status)}</div>${route(s)}<p class="muted">${E(s.goods)} · ${money(s.rate)} agreed driver rate</p>${s.status==='In transit'?`<button class="btn light" onclick="startBrowserTracking('${s.id}')">Share location while this page is open</button>`:''}${controls(s)}</section>`).join(''):'<section class="card empty"><h2>No active assigned job.</h2><p>Job offers will appear after a broker offers a suitable delivery.</p><button class="btn" onclick="nav(\'offers\')">View job offers (${offers.length})</button></section>'}</div><div><section class="card truckcard"><h2>${E(driverProfile.truck||'Your truck')}</h2><p>${E(driverProfile.type)} · ${E(driverProfile.kg)} kg<br>${E(driverProfile.area)}</p><span class="truckplate">${E(driverProfile.plate||'')}</span></section><section class="card" style="margin-top:20px">${noMap()}</section></div></div>`;}
let gpsWatches=new Map();
function startBrowserTracking(shipmentId){if(!navigator.geolocation){toast('This browser does not support location');return}if(gpsWatches.has(shipmentId)){navigator.geolocation.clearWatch(gpsWatches.get(shipmentId));gpsWatches.delete(shipmentId);toast('Location sharing stopped');return}const watch=navigator.geolocation.watchPosition(async pos=>{try{await api('/api/gps/location',{method:'POST',body:{shipmentId,latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,speed:pos.coords.speed,heading:pos.coords.heading,altitude:pos.coords.altitude}})}catch(e){toast(e.message);navigator.geolocation.clearWatch(watch);gpsWatches.delete(shipmentId)}},e=>toast(e.message),{enableHighAccuracy:true,maximumAge:15000,timeout:20000});gpsWatches.set(shipmentId,watch);toast('Sharing location while this page stays open');}
function realOffers(){let jobs=shipments.filter(s=>s.status==='Offered'&&s.offeredTo===sessionUser.id),market=shipments.filter(s=>s.status==='Ready to assign'&&!s.pickupDatePassedAt&&Date.parse(s.bidsExpiresAt)>Date.now()&&fitDriver(sessionUser,s));return title('Available work and offers','Submit a rate for compatible loads or respond to direct offers.')+`<h2>Direct offers</h2><div class="grid2">${jobs.length?jobs.map(s=>`<section class="card"><h2>${s.id}</h2>${route(s)}<p>${E(s.goods)} · ${money(s.rate)} driver rate</p><p class="muted">Offer expires ${E(s.offerExpiresAt||'when withdrawn by broker')}</p><button class="btn" onclick="transition('${s.id}','acceptJob')">Accept</button><button class="btn light" onclick="transition('${s.id}','decline')">Decline</button></section>`).join(''):'<p class="muted">No direct offers.</p>'}</div><h2 style="margin-top:25px">Open loads</h2><div class="grid2">${market.length?market.map(s=>{let bid=(s.bids||[]).find(x=>x.driverId===sessionUser.id);return `<section class="card"><h2>${s.id} · ${E(s.destination)}</h2>${route(s)}<p>${E(s.goods)} · ${E(s.date)} · ${E(s.window)}</p>${s.stops?.length?`<p>Stops: ${s.stops.map(x=>E(x.address||x)).join(' → ')}</p>`:''}<p class="muted">Bidding closes ${E(new Date(s.bidsExpiresAt).toLocaleString())}</p>${bid?`<div class="notice">Your bid: ${money(bid.rate)} · ${E(bid.note||'')}</div><button class="btn light" onclick="action('${s.id}','withdrawBid')">Withdraw bid</button>`:''}<form onsubmit="submitBid(event,'${s.id}')">${field('rate',bid?'Update your rate':'Your driver rate (CAD)','number',String(bid?.rate||''))}${field('note','Bid note','text',bid?.note||'Optional')}<button class="btn">${bid?'Update bid':'Submit bid'}</button></form></section>`}).join(''):'<p class="muted">No compatible open loads.</p>'}</div>`;}
async function submitBid(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));await action(id,'bid',{rate:Number(d.rate),note:d.note})}
function realProfile(){if(role==='store')return title('Your store profile','Saved account details for receiving deliveries.')+`<form class="card wizard" onsubmit="saveProfile(event)">${field('name','Store / business name','text','',sessionUser.name)}<div class="field"><label>Email address</label><input value="${E(sessionUser.email)}" readonly></div><div class="grid2">${field('address','Store delivery address','text','',sessionUser.profile.address)}${field('contact','Receiving contact','text','',sessionUser.profile.contact)}${field('phone','Contact phone','tel','',sessionUser.profile.phone)}</div><button class="btn">Save profile</button></form>`;return title('Driver and truck profile','Contact YYC to arrange verified changes to approved truck details.')+`<section class="card"><div class="row between"><h2>${E(sessionUser.name)}</h2>${badge(driverProfile.approved?'Approved':'Pending review')}</div><div class="review">${[['Email',sessionUser.email],['Phone',sessionUser.profile.phone],['Truck',driverProfile.truck],['Plate',driverProfile.plate],['Type',driverProfile.type],['Payload',driverProfile.kg+' kg'],['Pallet capacity',driverProfile.pallets],['Service area',driverProfile.area],['Liftgate',driverProfile.liftgate?'Yes':'No']].map(([k,v])=>`<div><span>${k}</span><b>${E(v)}</b></div>`).join('')}</div><h2 style="margin-top:24px">Compliance documents</h2><form class="grid2" onsubmit="uploadComplianceDocument(event)"><div class="field"><label>Document type</label><select name="documentType"><option value="license">Driver licence</option><option value="registration">Truck registration</option><option value="insurance">Insurance</option></select></div><div class="field"><label>File</label><input name="file" type="file" accept=".pdf,.jpg,.jpeg,.png" required></div><div class="field"><label>Expiry date</label><input name="expiryDate" type="date"></div><button class="btn">Upload for review</button></form><div id="myDocuments">Loading documents…</div><button class="btn light" onclick="beginMfaEnrollment()">Set up authenticator MFA</button></section>`;}
function fitDriver(d,s){let t=d.truck;return d.approved&&t?.approved&&!d.disabled&&t.type===s.type&&t.kg>=s.kg&&t.pallets>=s.pallets&&(!s.unloading?.includes('Liftgate')||t.liftgate)}
controls=function(s){if(role==='admin'){if(s.status==='Awaiting quote')return `<h2>Prepare quotation v${s.quoteVersion}</h2><form onsubmit="sendQuote(event,'${s.id}')" style="margin-top:18px"><div class="grid2">${field('price','Customer quote (CAD)','number')}${field('rate','Driver offer (CAD)','number')}</div>${field('expiryHours','Quote valid for (hours)','number','','72')}<div class="notice">Amounts exclude 5% GST, which is added to the customer's invoice. Unaccepted quotes expire automatically.</div><button class="btn" style="margin-top:15px">Issue quotation</button></form>`;if(s.status==='Ready to assign'){let list=serverDrivers.filter(d=>fitDriver(d,s));return `<h2>Driver bids</h2>${(s.bids||[]).map(b=>{let d=serverDrivers.find(x=>x.id===b.driverId);return `<div class="activity"><span>${E(d?.name||'Driver')} · ${money(b.rate)} · ${E(b.note||'')}</span><button class="btn light small" onclick="action('${s.id}','acceptBid',{driverId:'${b.driverId}'})">Select bid</button></div>`}).join('')||'<p class="muted">No bids submitted.</p>'}<h2 style="margin-top:18px">Offer directly to driver</h2>${list.length?`<div class="field" style="margin-top:18px"><label for="realDriverChoice">Approved suitable driver</label><select id="realDriverChoice">${list.map(d=>`<option value="${d.id}">${E(d.name)} · ${E(d.truck.plate)}</option>`).join('')}</select></div><p class="muted" style="font-size:12px">Driver rate: ${money(s.rate)}</p><button class="btn" style="margin-top:16px" onclick="transition('${s.id}','offer')">Send job offer</button>`:'<p class="muted" style="margin-top:16px">No approved driver/truck fits this cargo. Review registrations and requirements.</p>'}<div class="notice">The server rechecks eligibility and active-job conflicts when offering and accepting.</div>`;}return `<h2>Next step</h2><p class="muted" style="margin-top:15px">${s.status==='Quote ready'?'Waiting for the customer to accept this quote.':s.status==='Offered'?'Waiting for the selected driver to respond.':s.status==='Assigned'?'Driver accepted. Awaiting pickup.':s.status==='In transit'?'Awaiting delivery evidence from the assigned driver.':s.status==='Delivered'?'Delivery evidence is recorded. Payment remains a separate business process.':'This request was cancelled.'}</p>`;}
 if(role==='store'){if(s.status==='Quote ready')return `<h2>Review quotation v${s.quoteVersion}</h2><div class="jobprice" style="margin:20px 0">${money(s.price)}</div><p class="muted">Review the route and cargo before accepting.</p><button class="btn" style="margin-top:18px" onclick="transition('${s.id}','acceptQuote')">Accept quotation</button>`;return `<h2>Next step</h2><p class="muted" style="margin-top:15px">${s.status==='Awaiting quote'?'YYC is reviewing this request.':s.status==='Delivered'?'Delivery evidence has been recorded.':'Follow the milestones and driver assignment for this request.'}</p>${['Awaiting quote','Quote ready'].includes(s.status)?`<button class="btn light" style="margin-top:18px" onclick="transition('${s.id}','cancel')">Cancel request</button>`:''}`;}
 if(s.status==='Offered')return `<h2>Job offer</h2><p style="margin:15px 0">Driver rate: ${money(s.rate)}</p><button class="btn" onclick="transition('${s.id}','acceptJob')">Accept job</button><button class="btn light" onclick="transition('${s.id}','decline')">Decline</button>`;
 if(s.status==='Assigned')return `<h2>Pickup actions</h2><div class="row wrap" style="margin-top:18px"><button class="btn light" onclick="markArrival('${s.id}')">Record pickup arrival</button><button class="btn" onclick="transition('${s.id}','pickup')">Confirm goods picked up</button></div><button class="exceptionbtn" onclick="reportIssue('${s.id}')">Report an issue</button>`;
 if(s.status==='In transit')return `<h2>Record delivery</h2>${s.issue&&!s.issue.resolved?'<div class="alertbadge" style="margin-top:15px">YYC must resolve the open exception before completion.</div>':''}<form onsubmit="completeDelivery(event,'${s.id}')" style="margin-top:18px">${field('pod','Delivery receipt reference')}${field('recipient','Received by')}<button class="btn" ${s.issue&&!s.issue.resolved?'disabled':''}>Confirm delivery</button></form><div class="row wrap" style="margin-top:16px"><button class="btn light" onclick="markArrival('${s.id}')">Record store arrival</button><button class="textbtn" onclick="reportIssue('${s.id}')">Report an issue</button></div>`;
 return '<h2>Delivery record</h2><p class="muted" style="margin-top:15px">Review the stored delivery evidence and event history.</p>';
};
async function action(id,name,data={}){if(pendingAction)return;let s=shipments.find(s=>s.id===id);if(!s){toast('Refresh to load this delivery.');return}pendingAction=true;try{await api('/api/shipments/'+id+'/actions',{method:'POST',body:{...data,action:name,version:s.version}});await loadState();render();caseTab='Overview';openDelivery(id);toast('Saved on server');}catch(e){if(e.status===409){try{await loadState();render();openDelivery(id)}catch{}}fail(e);}finally{pendingAction=false;}}
transition=async function(id,name){let data={};if(name==='offer')data.driverId=$('#realDriverChoice')?.value;await action(id,name,data)};
sendQuote=async function(e,id){e.preventDefault();let f=new FormData(e.target);await action(id,'quote',{price:Number(f.get('price')),rate:Number(f.get('rate')),expiryHours:Number(f.get('expiryHours'))||72})};
completeDelivery=async function(e,id){e.preventDefault();await action(id,'deliver',Object.fromEntries(new FormData(e.target)))};
markArrival=async function(id){await action(id,'arrival')};
markStop=async function(id,index,next){if(next==='arriveStop'){await action(id,next,{stopIndex:index});return}let note=prompt('Stop note (optional)')||'',receipt=prompt('Receipt reference (optional)')||'';await action(id,next,{stopIndex:index,note,receipt})};
bookStep=async function(e){e.preventDefault();Object.assign(bookingData,Object.fromEntries(new FormData(e.target)));if(bookingStep<3){bookingStep++;render();window.scrollTo(0,0);return}if(pendingAction)return;pendingAction=true;try{await api('/api/shipments',{method:'POST',body:{...bookingData,stops:(bookingData.stops||'').split('\n').map(x=>x.trim()).filter(Boolean),pallets:Number(bookingData.pallets),kg:Number(bookingData.kg)}});await loadState();bookingData={};bookingStep=1;page='shipments';render();toast('Delivery request saved');}catch(error){let el=$('#bookError');if(el)el.textContent=error.message;else fail(error);}finally{pendingAction=false;}};
saveProfile=async function(e){e.preventDefault();try{await api('/api/profile',{method:'PATCH',body:Object.fromEntries(new FormData(e.target))});await loadState();render();toast('Profile saved');}catch(error){fail(error)}};
reportIssue=function(id){$('#overlay').innerHTML=`<div class="drawer" onclick="if(event.target===this)closeDrawer()"><section class="drawerbody" role="dialog" aria-modal="true" aria-label="Report delivery issue"><div class="row between"><h2>Report a delivery issue</h2><button class="close" aria-label="Close issue report" onclick="closeDrawer()">×</button></div><form class="card" onsubmit="saveIssue(event,'${id}')">${select('reason','What happened?',['Store closed / recipient unavailable','Loading or unloading delay','Truck breakdown','Cargo damaged / quantity mismatch','Other'])}<div class="field"><label for="issueNote">Details</label><textarea id="issueNote" name="note" required></textarea></div><button class="btn">Save issue</button><div class="notice">An open exception prevents delivery completion until YYC records a resolution.</div></form></section></div>`;$('.close').focus()};
saveIssue=async function(e,id){e.preventDefault();await action(id,'issue',Object.fromEntries(new FormData(e.target)))};
resolveIssue=function(id){$('#overlay').innerHTML=`<div class="drawer" onclick="if(event.target===this)closeDrawer()"><section class="drawerbody" role="dialog" aria-modal="true" aria-label="Resolve delivery exception"><div class="row between"><h2>Resolve exception</h2><button class="close" aria-label="Close resolution" onclick="closeDrawer()">×</button></div><form class="card" onsubmit="saveResolution(event,'${id}')"><div class="field"><label for="resolutionNote">Resolution and agreed next action</label><textarea id="resolutionNote" name="resolution" required></textarea></div><button class="btn">Record resolution</button><div class="notice">This does not itself mark the shipment delivered.</div></form></section></div>`;$('.close').focus()};
saveResolution=async function(e,id){e.preventDefault();await action(id,'resolve',Object.fromEntries(new FormData(e.target)))};
const starterEdit=editShipment;
editShipment=function(id){starterEdit(id);let note=$('#overlay .notice');if(note)note.textContent='Before pickup, a material change archives the earlier quote and invalidates its acceptance and assignment. A new quote and acceptance will be required.';let submit=$('#overlay form button.btn');if(submit)submit.textContent='Apply change and require a new quote'};
saveShipmentChange=async function(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));await action(id,'change',{...d,kg:Number(d.kg),pallets:Number(d.pallets)})};
caseOverview=function(s){let accepted=!['Awaiting quote','Quote ready','Cancelled'].includes(s.status);return `<div class="casemetrics"><div><small>REQUESTED PICKUP</small><b>${E(s.date)}</b></div><div><small>VEHICLE</small><b>${E(s.type)}</b></div><div><small>${role==='driver'?'DRIVER RATE':'CUSTOMER QUOTE'}</small><b>${money(role==='driver'?s.rate:s.price)}</b></div></div><div class="casegrid"><div><section class="card"><h2 style="margin-bottom:18px">Pickup and delivery</h2>${route(s)}${s.stops?.length?'<div class="casecontact"><b>Intermediate stops</b>'+s.stops.map((x,i)=>'<div>'+(i+1)+'. '+E(x.address||x)+' '+E(x.contact||'')+' '+E(x.window||'')+' · '+E(x.serviceMinutes||20)+' min · '+E(s.stopProgress?.[i]?.completedAt?(s.stopProgress[i].late?'Completed late':'Completed'):s.stopProgress?.[i]?.arrivedAt?'Arrived':'Pending')+(role==='driver'&&s.status==='In transit'&&!s.stopProgress?.[i]?.completedAt?' <button class=\"btn light small\" onclick=\"markStop(\\\''+s.id+'\\\','+i+',\\\''+(s.stopProgress?.[i]?.arrivedAt?'completeStop':'arriveStop')+'\\\')\">'+(s.stopProgress?.[i]?.arrivedAt?'Complete stop':'Record arrival')+'</button>':'')+'</div>').join('')+'</div>':''}<div class="casecontact"><b>${E(s.goods)}</b>${s.pallets} pallets · ${s.kg} kg<br>${E(s.unloading)}<br>${E(s.cargoNotes||'')}</div><div class="casecontact"><b>Receiving arrangements</b>${E(s.hours)}<br>${E(s.receivingContact)}<br>${E(s.appointment||'No appointment reference')}</div><div class="casecontact"><b>Pickup contact</b>${E(s.pickupContact)}</div><div class="casecontact"><b>Instructions</b>${E(s.notes||'None supplied')}</div></section><section class="card"><h2>Progress</h2>${journeyProgress(s)}${s.arrivedAt?'<div class="notice">Arrival recorded at '+E(s.arrivedAt)+'. Handover is confirmed separately.</div>':''}</section>${s.pod?`<section class="card"><h2>Recorded delivery evidence</h2><p style="margin-top:15px">Receipt: ${E(s.pod)}<br>Received by: ${E(s.recipient)}</p></section>`:''}</div><div><section class="card"><div class="eyebrow muted" style="margin-bottom:18px">NEXT ACTION</div>${controls(s)}</section><section class="card"><h2>Assignment</h2><p class="muted" style="margin:15px 0">${E(driverLabel(s))}</p><div class="microchecks">${accepted?'✓ Current quote accepted':'○ Quote acceptance required'}<br>${s.driver?'✓ Driver assignment recorded':'○ Assignment pending'}</div><div class="notice">The server checks permissions, versions, approval and active-job conflicts for each action.</div></section>${s.issue?`<section class="card"><span class="tag ${s.issue.resolved?'':'amber'}">${s.issue.resolved?'RESOLVED':'OPEN EXCEPTION'}</span><h3 style="margin-top:15px">${E(s.issue.reason)}</h3><p class="muted" style="font-size:12px;margin-top:12px">${E(s.issue.note)}</p>${s.issue.resolution?'<div class="notice">'+E(s.issue.resolution)+'</div>':''}${role==='admin'&&!s.issue.resolved?`<button class="btn light" style="margin-top:18px" onclick="resolveIssue('${s.id}')">Record a resolution</button>`:''}</section>`:''}</div></div>${role==='admin'&&!['In transit','Delivered','Cancelled'].includes(s.status)?`<section class="card changecontrol"><div><h3>Material shipment change</h3><p>A new quote will be required if cargo or destination changes.</p></div><button class="btn light small" onclick="editShipment('${s.id}')">Review a change</button></section>`:''}`;};
caseTracking=function(s){return `<section class="card">${noMap()}<p class="muted">Assigned driver: ${E(driverLabel(s))}</p>${journeyProgress(s)}</section>`};
caseHistory=function(s){return `<section class="card"><h2>Server event history</h2><div style="margin-top:25px">${(s.history||[]).map(h=>`<div class="timelineentry"><b>${E(h.text)}</b><small>${E(h.actor)} · ${E(h.time)}</small></div>`).join('')}</div></section>${s.quoteArchive?.length?`<section class="card" style="margin-top:18px"><h2>Previous quotation versions</h2>${s.quoteArchive.map(q=>`<div class="archivedquote"><b>v${q.version} · ${money(role==='driver'?q.rate:q.price)}</b><span>${E(q.destination)} · ${q.kg} kg · ${q.pallets} pallets</span><small>${E(q.reason)}</small></div>`).join('')}</section>`:''}`};
caseDocuments=function(s){return `<section class="card"><h2>Stored transaction summaries</h2><p class="muted" style="font-size:12px;margin:15px 0">These are database records, not uploaded files or issued PDF documents.</p><div class="docitem">${icon('file')}<div><b>Quotation v${s.quoteVersion}</b><small>${money(role==='driver'?s.rate:s.price)} · ${E(s.status)}</small></div></div><div class="docitem">${icon('box')}<div><b>Cargo summary</b><small>${E(s.goods)} · ${s.pallets} pallets · ${s.kg} kg</small></div></div><div class="docitem">${icon('file')}<div><b>Delivery receipt reference</b><small>${s.pod?E(s.pod)+' · '+E(s.recipient):'No evidence recorded yet'}</small></div></div><div class="notice">Private file uploads, insurance attachments, photos and electronic signatures are not implemented in this starter.</div></section>`};
const starterPaint=paintCase;
