// Billing actions use the existing Stripe intent/webhook endpoints and PDF generator.
caseDocuments=function(s){let billing=`<section class="card"><h2>Billing</h2><p class="muted">Payment ${E(s.paymentStatus||'pending')} · ${s.paymentAmount?money(s.paymentAmount):'Amount due: '+money((Number(s.price)||0)*1.05)}${role==='driver'?' · payout '+E(s.payoutStatus||'pending'):''}</p>${s.status==='Delivered'&&role==='store'&&s.paymentStatus!=='succeeded'?`<div id="pay-${s.id}" style="margin:14px 0"></div><button class="btn" onclick="startShipmentPayment('${s.id}')">${s.paymentStatus==='processing'?'Continue payment':'Pay invoice'}</button>`:''}${s.status==='Delivered'&&role!=='driver'?`<button class="btn light" style="margin-left:8px" onclick="downloadInvoice('${s.id}')">Download PDF invoice</button>`:''}${role==='admin'&&s.status==='Delivered'&&paymentSettled(s)&&s.payoutStatus!=='paid'?`<button class="btn light" onclick="createDriverPayout('${s.id}')">Issue driver payout</button>`:''}</section>`;return billing+`<section class="card"><h2>Shipment documents</h2><div class="docitem"><div><b>Quotation v${s.quoteVersion}</b><small>${money(role==='driver'?s.rate:s.price)} · ${E(s.status)}</small></div></div><div class="docitem"><div><b>Delivery receipt</b><small>${s.pod?E(s.pod)+' · '+E(s.recipient):'No evidence recorded'}</small></div></div></section>`};
async function downloadInvoice(id){try{let r=await fetch('/api/shipments/'+id+'/invoice',{credentials:'same-origin'});if(!r.ok){let x=await r.json();throw Error(x.error||'Invoice download failed')}let a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='invoice-'+id+'.pdf';a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}}
async function startShipmentPayment(id){try{let conf=await api('/api/payments/config');if(!conf.publishableKey||!window.Stripe)throw Error('Online card payment is not configured.');let paymentResult=await api('/api/shipments/'+id+'/payment',{method:'POST',body:{}});if(paymentResult.settled){toast(paymentResult.message);await loadState();render();return}let paymentIntent=paymentResult.paymentIntent;let host=document.getElementById('pay-'+id);if(!host)return;let stripe=Stripe(conf.publishableKey),elements=stripe.elements({clientSecret:paymentIntent.clientSecret}),payment=elements.create('payment');host.innerHTML='';payment.mount(host);let button=host.nextElementSibling;button.textContent='Confirm payment';button.onclick=async()=>{button.disabled=true;let result=await stripe.confirmPayment({elements,confirmParams:{return_url:location.href},redirect:'if_required'});if(result.error){toast(result.error.message);button.disabled=false}else{await loadState();render();toast('Payment submitted; final status arrives by webhook')}}}catch(e){toast(e.message)}}
async function createDriverPayout(id){if(!confirm('Create the Stripe Connect payout for this completed delivery?'))return;try{await api('/api/admin/shipments/'+id+'/payout',{method:'POST',body:{}});await loadState();render();toast('Payout sent')}catch(e){toast(e.message)}}
const routeMaps=new Map();function decodeRoute(s){let i=0,lat=0,lng=0,out=[];while(i<s.length){let b,shift=0,result=0;do{b=s.charCodeAt(i++)-63;result|=(b&31)<<shift;shift+=5}while(b>=32);lat+=(result&1)?~(result>>1):(result>>1);shift=0;result=0;do{b=s.charCodeAt(i++)-63;result|=(b&31)<<shift;shift+=5}while(b>=32);lng+=(result&1)?~(result>>1):(result>>1);out.push([lat/1e5,lng/1e5])}return out}
loadTrackingCards=async function(){for(const s of shipments.filter(x=>x.driver&&!['Delivered','Cancelled'].includes(x.status))){let el=document.getElementById('tracking-'+s.id);if(!el)continue;try{let {location:l}=await api('/api/shipments/'+s.id+'/location');if(!l){el.textContent='No driver location yet. Driver must enable location sharing.';continue}let p=[Number(l.latitude),Number(l.longitude)],entry=routeMaps.get(s.id);if(!entry){el.innerHTML=`<div>Last location: <span class="track-time"></span> · accuracy <span class="track-accuracy"></span>m</div><div id="live-map-${s.id}" style="height:290px;margin-top:12px;border-radius:10px"></div><div class="track-eta muted" style="margin-top:8px">Loading route and ETA…</div>`;entry={map:null,marker:null,lastRoute:0};routeMaps.set(s.id,entry)}el.querySelector('.track-time').textContent=new Date(l.recorded_at).toLocaleTimeString();el.querySelector('.track-accuracy').textContent=Math.round(Number(l.accuracy)||0);if(!window.L){el.querySelector('.track-eta').textContent='Map library unavailable.';continue}if(!entry.map){entry.map=L.map('live-map-'+s.id).setView(p,12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(entry.map);entry.marker=L.marker(p).addTo(entry.map).bindPopup('Driver location');setTimeout(()=>entry.map.invalidateSize(),100)}else{entry.marker.setLatLng(p);entry.map.panTo(p,{animate:true,duration:.8})}if(Date.now()-entry.lastRoute>60000){entry.lastRoute=Date.now();try{let points=[...(s.stops||[]).map(x=>x.address||x),s.destination],origin={lat:p[0],lng:p[1]},seconds=0;entry.routeLayers?.forEach(x=>entry.map.removeLayer(x));entry.routeLayers=[];for(let destination of points){let d=await api('/api/maps/directions',{method:'POST',body:{origin,destination}});seconds+=d.durationInTraffic?.seconds||d.duration?.seconds||0;let line=L.polyline(decodeRoute(d.polyline),{color:'#c18b3c',weight:5,opacity:.85}).addTo(entry.map);entry.routeLayers.push(line);origin=destination}let bounds=L.latLngBounds([p,...entry.routeLayers.flatMap(x=>x.getLatLngs())]);entry.map.fitBounds(bounds.pad(.15));el.querySelector('.track-eta').textContent='Route ETA '+new Date(Date.now()+seconds*1000).toLocaleString()}catch{el.querySelector('.track-eta').textContent='Live driver pin shown; road route and ETA require Google Maps configuration.'}}}catch(e){el.textContent=e.message}}};
const previousControls=controls;controls=function(s){let html=previousControls(s);if(role==='driver'&&s.status==='Assigned')html+=`<button class="btn light" style="margin-top:14px" onclick="withdrawAssignment('${s.id}')">Withdraw before pickup</button>`;if(role==='admin'&&!['Delivered','Cancelled'].includes(s.status))html+=`<button class="btn light" style="margin-top:14px" onclick="brokerCancel('${s.id}')">${s.cancellationRequest?.status==='open'?'Approve cancellation':'Cancel with reason'}</button>`;return html};
async function withdrawAssignment(id){let reason=prompt('Why are you withdrawing this assignment?');if(!reason?.trim())return;await action(id,'withdrawAssignment',{reason})}async function brokerCancel(id){let reason=prompt('Required cancellation reason for the audit record');if(!reason?.trim())return;await action(id,'cancel',{reason})}
