const basicShipmentTable=table;let activeShipmentSearch='',activeShipmentStatus=localStorage.getItem('yyc-shipment-status')||'',shipmentNextCursor=null;const loadStateFirstPage=loadState;loadState=async function(){let priorUser=sessionUser?.id,priorShipments=shipments.slice(),priorCursor=shipmentNextCursor;await loadStateFirstPage();let p=await api('/api/state?limit=100');if(priorUser&&priorUser===sessionUser?.id){let firstIds=new Set(shipments.map(s=>s.id));shipments.push(...priorShipments.filter(s=>!firstIds.has(s.id)));shipmentNextCursor=priorCursor}else shipmentNextCursor=p.next||null};
table=function(rows){let statuses=[...new Set(shipments.map(s=>s.status))].sort(),needle=activeShipmentSearch.toLowerCase();let visible=rows.filter(s=>(!activeShipmentStatus||s.status===activeShipmentStatus)&&(!needle||[s.id,s.customer,s.destination,s.pickup,s.goods,s.driverName].some(x=>String(x||'').toLowerCase().includes(needle))));let original=basicShipmentTable(visible);let toolbar=`<div class="shipment-tools"><label><span class="sr-only">Search deliveries</span><input type="search" value="${E(activeShipmentSearch)}" placeholder="Search reference, store, route or goods" aria-label="Search deliveries" oninput="activeShipmentSearch=this.value;refreshShipmentFilter()"></label><label><span class="sr-only">Filter by status</span><select aria-label="Filter deliveries by status" onchange="activeShipmentStatus=this.value;localStorage.setItem('yyc-shipment-status',this.value);refreshShipmentFilter()"><option value="">All statuses (${rows.length})</option>${statuses.map(x=>`<option value="${E(x)}" ${x===activeShipmentStatus?'selected':''}>${E(x)}</option>`).join('')}</select></label><button class="btn light small" onclick="exportVisibleShipments()">Export CSV</button><button class="btn light small" onclick="activeShipmentSearch='';activeShipmentStatus='';localStorage.removeItem('yyc-shipment-status');render()">Clear filters</button></div>`;return toolbar+'<div id="filteredShipmentTable">'+original+'</div>'+(shipmentNextCursor?'<button class="btn light" style="margin:14px 0" onclick="loadMoreShipments()">Load older deliveries</button>':'')};
async function loadMoreShipments(){if(!shipmentNextCursor)return;try{let p=await api('/api/state?limit=100&after='+encodeURIComponent(shipmentNextCursor));shipments.push(...p.shipments);shipmentNextCursor=p.next||null;render()}catch(e){toast(e.message)}}
