function exportVisibleShipments(){let rows=shipments.filter(s=>(!activeShipmentStatus||s.status===activeShipmentStatus)&&(!activeShipmentSearch||[s.id,s.customer,s.destination,s.pickup,s.goods,s.driverName].some(x=>String(x||'').toLowerCase().includes(activeShipmentSearch.toLowerCase()))));let keys=['id','customer','status','pickup','destination','date','window','goods','pallets','kg','price','rate','paymentStatus','payoutStatus'];let csv=[keys.join(','),...rows.map(s=>keys.map(k=>{let v=String(s[k]??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"'}).join(','))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='yyc-deliveries.csv';a.click();URL.revokeObjectURL(a.href)}

// Operations reports are derived from the visible, authorized shipment records.
navs.admin.push(['reports','grid','Reports']);navs.driver.push(['schedule','clock','My schedule']);const contentBeforeReportsAndSchedule=content;content=function(){if(role==='admin'&&page==='reports')return operationsReport();if(role==='driver'&&page==='schedule')return driverSchedule();return contentBeforeReportsAndSchedule()};
function operationsReport(){let rows=shipments,done=rows.filter(s=>s.status==='Delivered'),cancelled=rows.filter(s=>s.status==='Cancelled'),active=rows.filter(s=>!['Delivered','Cancelled'].includes(s.status)),exceptions=rows.filter(s=>s.issue&&!s.issue.resolved),windowed=done.filter(s=>s.stopProgress?.length),late=windowed.filter(s=>s.stopProgress.some(x=>x.late)),base=Math.max(1,windowed.length),data=[['Delivered',done.length],['Late stop windows',late.length],['Open exceptions',exceptions.length],['Cancelled',cancelled.length]];return title('Operational reports','Delivery outcomes and workload from your current shipment records.')+stats([['Deliveries','Current records',rows.length,'box'],['Active','In progress',active.length,'truck'],['On-time stops','Completed scheduled deliveries',windowed.length?`${Math.round(100*(windowed.length-late.length)/base)}%`:'No windowed deliveries','check'],['Open exceptions','Need follow-up',exceptions.length,'clock']])+`<div class="card"><h2>Outcome overview</h2><div class="reportbars">${data.map(([label,n])=>`<div class="reportbar"><span>${E(label)}</span><div><i style="width:${Math.min(100,n/Math.max(1,rows.length)*100)}%"></i></div><b>${n}</b></div>`).join('')}</div><p class="muted" style="margin-top:15px">On-time rate uses completed receiving-stop windows recorded in shipment evidence. Revenue and utilization require finalized billing and driver shift records.</p></div><div class="card" style="margin-top:18px"><div class="row between"><h2>Open exceptions</h2><button class="btn light small" onclick="nav('alerts')">Review queue</button></div>${exceptions.map(s=>`<div class="activity"><span><b>${E(s.id)}</b> · ${E(s.issue.severity||'normal')} · due ${E(s.issue.dueAt?new Date(s.issue.dueAt).toLocaleString():'not set')} · ${E(s.issue.reason)}</span><button class="btn light small" onclick="openDelivery('${s.id}')">Open</button></div>`).join('')||'<p class="muted" style="margin-top:12px">No unresolved exceptions in these records.</p>'}</div>`}
function driverSchedule(){let jobs=shipments.filter(s=>s.driverId===sessionUser.id&&!['Delivered','Cancelled'].includes(s.status)).sort((a,b)=>(a.date||'').localeCompare(b.date||''));return title('My schedule','Assigned deliveries ordered by requested pickup date.')+`<div class="grid2">${jobs.map(s=>`<section class="card"><div class="row between"><h2>${E(s.date)} · ${E(s.window)}</h2>${badge(s.status)}</div><p style="margin-top:14px"><b>${E(s.pickup)}</b> → ${E(s.destination)}</p><p class="muted" style="margin-top:8px">${E(s.goods)} · ${s.pallets} pallets · ${s.kg} kg · ${money(s.rate)}</p>${s.stops?.length?`<ol class="schedule-stops">${s.stops.map(x=>`<li>${E(x.address||x)} · ${E(x.window||'Flexible')} · ${E(x.serviceMinutes||20)} min</li>`).join('')}</ol>`:''}<button class="btn light" style="margin-top:15px" onclick="openDelivery('${s.id}')">Open job</button></section>`).join('')||'<section class="card empty full">No assigned upcoming deliveries.</section>'}</div>`}

// Persistent in-app inbox with per-user read state.
