function exceptionQueue(){let open=shipments.filter(s=>s.issue&&!s.issue.resolved).sort((a,b)=>Date.parse(a.issue.dueAt||'9999')-Date.parse(b.issue.dueAt||'9999'));return title('Exception queue','Assign an owner, track a due time, and record the resolution.')+`<div class="grid2">${open.map(s=>{let overdue=s.issue.dueAt&&Date.parse(s.issue.dueAt)<Date.now();return `<section class="card"><div class="row between"><h2>${E(s.id)} · ${E(s.issue.reason)}</h2><span class="tag ${overdue?'amber':''}">${overdue?'OVERDUE':E(s.issue.severity||'normal').toUpperCase()}</span></div><p style="margin-top:12px">${E(s.issue.note)}</p><p class="muted" style="margin:10px 0">Owner: ${s.issue.assignedTo===sessionUser.id?'You':s.issue.assignedTo?'Assigned broker':'Unassigned'} · Due: ${E(s.issue.dueAt?new Date(s.issue.dueAt).toLocaleString():'not set')}</p><button class="btn light" onclick="action('${s.id}','assignIssue',{assigneeId:sessionUser.id})">Assign to me</button><button class="btn" onclick="openDelivery('${s.id}')">Review and resolve</button></section>`}).join('')||'<section class="card empty full">No open exceptions.</section>'}</div>`}

