function duplicateShipment(id){let s=shipments.find(x=>x.id===id);if(!s)return;bookingData={pickup:s.pickup,destination:s.destination,date:'',window:s.window,goods:s.goods,pallets:s.pallets,kg:s.kg,type:s.type,unloading:s.unloading,notes:s.notes||'',stops:(s.stops||[]).map(x=>typeof x==='string'?x:[x.address,x.contact,x.window,x.serviceMinutes].filter(Boolean).join(' | ')).join('\n')};bookingStep=1;page='booking';render();toast('Review the copied request and choose a new date')}
