const profileBeforeAvailability=realProfile;realProfile=function(){let html=profileBeforeAvailability();if(role!=='driver')return html;queueMicrotask(loadDriverAvailability);return html+`<section class="card" style="margin-top:20px"><h2>Working availability</h2><p class="muted" style="margin:8px 0 16px">Dispatch checks these hours, days, and break before offering or assigning a delivery.</p><form id="driverAvailability" onsubmit="saveDriverAvailability(event)"><fieldset class="availability-days"><legend>Working days</legend>${[['0','Sun'],['1','Mon'],['2','Tue'],['3','Wed'],['4','Thu'],['5','Fri'],['6','Sat']].map(([v,l])=>`<label><input type="checkbox" name="days" value="${v}">${l}</label>`).join('')}</fieldset><div class="grid2">${field('workStart','Start time','time','','08:00')}${field('workEnd','End time','time','','17:00')}${field('breakStart','Break starts (optional)','time','','',false)}${field('breakEnd','Break ends (optional)','time','','',false)}</div><button class="btn">Save availability</button></form></section>`};
async function loadDriverAvailability(){let f=document.querySelector('#driverAvailability'),a=sessionUser?.profile?.availability;if(!f)return;if(a){for(let d of a.days||[])if(f.querySelector(`[name="days"][value="${d}"]`))f.querySelector(`[name="days"][value="${d}"]`).checked=true;f.elements.workStart.value=a.startTime;f.elements.workEnd.value=a.endTime;f.elements.breakStart.value=a.breakStart||'';f.elements.breakEnd.value=a.breakEnd||''}else for(let d of [1,2,3,4,5])f.querySelector(`[name="days"][value="${d}"]`).checked=true}
async function saveDriverAvailability(e){e.preventDefault();let f=e.target,availability={days:[...f.querySelectorAll('[name="days"]:checked')].map(x=>Number(x.value)),startTime:f.elements.workStart.value,endTime:f.elements.workEnd.value,breakStart:f.elements.breakStart.value,breakEnd:f.elements.breakEnd.value};try{await api('/api/profile',{method:'PATCH',body:{name:sessionUser.name,availability}});await loadState();render();toast('Availability saved and used for dispatch checks')}catch(x){toast(x.message)}}
const baseOperationsReport=operationsReport;operationsReport=function(){let html=baseOperationsReport(),collected=shipments.filter(s=>s.paymentStatus==='succeeded').reduce((a,s)=>a+Number(s.paymentAmount||0),0),paidOut=shipments.filter(s=>s.payoutStatus==='paid').reduce((a,s)=>a+Number(s.payoutAmount||0),0),failed=shipments.filter(s=>s.paymentStatus==='failed').length;return html.replace('<div class="card"><h2>Outcome overview</h2>',`${shipmentNextCursor?'<button class="btn light" style="margin-bottom:18px" onclick="loadMoreShipments()">Load more history for complete totals</button>':'<p class="muted" style="margin-bottom:15px">All available shipment records are loaded.</p>'}<div class="card" style="margin-bottom:18px"><h2>Payments and payouts</h2><div class="grid3" style="margin-top:16px"><div><small>COLLECTED</small><h3>${money(collected)}</h3></div><div><small>DRIVER PAYOUTS</small><h3>${money(paidOut)}</h3></div><div><small>FAILED PAYMENTS</small><h3>${failed}</h3></div></div><p class="muted" style="margin-top:12px">Totals include only loaded shipment records; load all history to reconcile the full set.</p></div><div class="card"><h2>Outcome overview</h2>`)};

setInterval(async()=>{if(!sessionUser||document.hidden||pendingAction||refreshInFlight||page==='booking'||page==='profile'||$('#overlay')?.innerHTML.trim())return;refreshInFlight=true;try{let previous=shipments.map(s=>s.id+':'+s.version).join('|');await loadState();let current=shipments.map(s=>s.id+':'+s.version).join('|');if(previous!==current)render();}catch(e){if(e.status===401)fail(e);}finally{refreshInFlight=false;}},15000);

// Requested workflows: quote revision, rescheduling, proof capture, partial receipt, and claims.
async function uploadShipmentEvidence(id,file){if(!file)return null;if(file.size>12*1024*1024)throw Error('Evidence files must be under 12 MB');let ext=file.name.split('.').pop().toLowerCase();if(!['jpg','jpeg','png','pdf'].includes(ext))throw Error('Use a JPG, PNG, or PDF evidence file');let signed=await api('/api/documents/upload-url',{method:'POST',body:{documentType:'pod',fileExtension:ext}}),put=await fetch(signed.uploadUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});if(!put.ok)throw Error('Evidence upload failed');let result=await api('/api/documents',{method:'POST',body:{s3Key:signed.s3Key,filename:file.name,documentType:'pod',fileSize:file.size,contentType:file.type,shipmentId:id}});return result.document.id}
const controlsBeforeProductWorkflows=controls;controls=function(s){let html=controlsBeforeProductWorkflows(s);if(role==='store'&&s.status==='Quote ready')html+=s.quoteRevisionRequest?.status==='open'?`<p class="notice">Quote revision requested: ${E(s.quoteRevisionRequest.reason)}</p><button class="btn light" style="margin-top:12px" onclick="action('${s.id}','withdrawQuoteRevision',{})">Withdraw revision request</button>`:`<button class="btn light" style="margin-top:12px" onclick="requestQuoteRevision('${s.id}')">Request quote revision</button>`;if(role==='admin'&&s.status==='Quote ready'&&s.quoteRevisionRequest?.status==='open')html+=`<form class="card" onsubmit="reviseQuote(event,'${s.id}')"><h3>Revision requested</h3><p>${E(s.quoteRevisionRequest.reason)}</p>${field('revisionPrice','Revised customer price','number','',String(s.price))}${field('revisionRate','Revised driver rate','number','',String(s.rate))}<button class="btn">Issue revised quotation</button> <button type="button" class="btn light" onclick="declineRequest('${s.id}','declineQuoteRevision','Why is the current quote staying as it is?')">Keep current quote</button></form>`;if(role==='store'&&['Quote ready','Ready to assign','Offered','Assigned'].includes(s.status))html+=s.rescheduleRequest?.status==='open'?`<p class="notice">Reschedule to ${E(s.rescheduleRequest.date)} (${E(s.rescheduleRequest.window)}) awaiting broker review.</p><button class="btn light" style="margin-top:12px" onclick="action('${s.id}','withdrawReschedule',{})">Withdraw reschedule request</button>`:`<button class="btn light" style="margin-top:12px" onclick="requestReschedule('${s.id}')">Request a new delivery time</button>`;if(role==='admin'&&s.rescheduleRequest?.status==='open')html+=`<div class="notice">Requested ${E(s.rescheduleRequest.date)} · ${E(s.rescheduleRequest.window)} · ${E(s.rescheduleRequest.reason)}</div>${['Quote ready','Ready to assign','Offered','Assigned'].includes(s.status)?`<button class="btn" onclick="action('${s.id}','approveReschedule',{})">Approve and recheck schedule</button> `:''}<button class="btn light" onclick="declineRequest('${s.id}','declineReschedule','Why is this reschedule declined?')">Decline</button>`;if(role==='store'&&s.status==='Delivered'&&s.claim?.status!=='open')html+=`<button class="btn light" style="margin-top:12px" onclick="openClaim('${s.id}')">Open delivery claim</button>`;if(role==='admin'&&s.claim?.status==='open')html+=`<div class="alertbadge">Open ${E(s.claim.type)} claim: ${E(s.claim.details)}</div><button class="btn" onclick="resolveShipmentClaim('${s.id}')">Record claim decision</button>`;if(role==='driver'&&s.status==='Assigned'){const old=`<button class="btn light" onclick="markArrival('${s.id}')">Record pickup arrival</button><button class="btn" onclick="transition('${s.id}','pickup')">Confirm goods picked up</button>`;const replacement=`<form onsubmit="recordPickup(event,'${s.id}')"><div class="grid2">${field('pickupReference','Pickup reference','text','', '',false)}${field('pickupSigner','Pickup signatory','text','', '',false)}</div><label>Pickup photo (optional)<input name="evidence" type="file" accept="image/jpeg,image/png,application/pdf"></label><button class="btn">Record pickup with proof</button></form>`;html=html.replace(old,replacement)}if(role==='driver'&&s.status==='In transit')html=html.replace('</form>',`<div class="grid2">${field('signatureName','Recipient signature name','text','', '',false)}${field('receivedQuantity','Quantity received','number','', '',false)}</div><div class="grid2">${field('shortage','Shortage details','text','', '',false)}${field('damage','Damage details','text','', '',false)}</div><label>Delivery photo / signed proof (optional)<input name="evidence" type="file" accept="image/jpeg,image/png,application/pdf"></label></form>`);return html};
async function requestQuoteRevision(id){let reason=prompt('What price, timing, route, or service detail should YYC review?');if(reason?.trim())await action(id,'requestQuoteRevision',{reason})}async function reviseQuote(e,id){e.preventDefault();let f=new FormData(e.target);await action(id,'reviseQuote',{price:Number(f.get('revisionPrice')),rate:Number(f.get('revisionRate'))})}
async function requestReschedule(id){let s=shipments.find(x=>x.id===id),date=prompt('New delivery date (YYYY-MM-DD)',s?.date||'');if(!date)return;let window=prompt('Window: 09:00–12:00, 13:00–16:00, or Flexible',s?.window||'Flexible');if(!window)return;let reason=prompt('Reason for the change');if(reason?.trim())await action(id,'requestReschedule',{date,window,reason})}
async function recordPickup(e,id){e.preventDefault();let f=e.target;try{let photoDocumentId=await uploadShipmentEvidence(id,f.elements.evidence.files[0]);await action(id,'pickup',{reference:f.elements.pickupReference.value,signatureName:f.elements.pickupSigner.value,photoDocumentId})}catch(x){toast(x.message)}}
completeDelivery=async function(e,id){e.preventDefault();let f=e.target,data=Object.fromEntries(new FormData(f));try{data.photoDocumentId=await uploadShipmentEvidence(id,f.elements.evidence?.files[0]);data.signatureName=data.signatureName||data.recipient;await action(id,'deliver',data)}catch(x){toast(x.message)}};
markStop=async function(id,index,next){if(next==='arriveStop'){await action(id,next,{stopIndex:index});return}let note=prompt('Stop note (optional)')||'',receipt=prompt('Receipt reference (optional)')||'',receivedQuantity=prompt('Quantity received (optional; enter 0 if refused)')||'',shortage=prompt('Shortage details (optional)')||'',damage=prompt('Damage details (optional)')||'',refused=prompt('Refused items (optional)')||'',signatureName=prompt('Recipient signature name (optional)')||'',photoDocumentId=null;if(confirm('Attach a photo or signed document for this stop?')){let file=await chooseEvidenceFile();if(file)try{photoDocumentId=await uploadShipmentEvidence(id,file)}catch(e){toast(e.message);return}}await action(id,next,{stopIndex:index,note,receipt,receivedQuantity,shortage,damage,refused,signatureName,photoDocumentId})};
function chooseEvidenceFile(){return new Promise(resolve=>{let input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,application/pdf';input.onchange=()=>resolve(input.files[0]||null);input.addEventListener('cancel',()=>resolve(null),{once:true});input.click()})}
async function openClaim(id){let type=prompt('Claim type: shortage, damage, late, or other','other'),details=prompt('Claim details and requested resolution');if(details?.trim())await action(id,'claim',{type,details})}async function resolveShipmentClaim(id){let decision=prompt('Decision: accepted, declined, credit, or replacement','accepted'),resolution=prompt('Decision notes');if(resolution?.trim())await action(id,'resolveClaim',{decision,resolution})}

// Store team access, scoped to the owner's shipment data and explicit permissions.
const profileBeforeTeamAndData=realProfile;realProfile=function(){let html=profileBeforeTeamAndData();if(role==='store'&&sessionUser.team?.isOwner){queueMicrotask(loadStoreTeam);html+=`<section class="card" style="margin-top:20px"><h2>Store team access</h2><p class="muted" style="margin:8px 0 16px">Invite an existing verified store account. Members can only access this store’s shipments.</p><form class="grid2" onsubmit="inviteStoreMember(event)">${field('teamEmail','Member account email','email')}<label><input type="checkbox" name="shipmentsWrite"> Allow shipment changes</label><label><input type="checkbox" name="billingRead"> Allow billing details</label><button class="btn">Grant access</button></form><div id="teamMembers"></div></section>`}return html+accountDataTools()};
function accountDataTools(){return `<section class="card" style="margin-top:20px"><h2>Your account data</h2><p class="muted" style="margin:8px 0 14px">Export your account record or submit a removal request. Completed delivery and financial records may be retained in anonymized form.</p><button class="btn light" onclick="downloadAccountExport()">Download my data</button><div id="deletionRequestState" style="margin-top:12px"></div><button id="requestAccountRemoval" class="btn light" style="margin-top:12px" onclick="requestAccountRemoval()">Request account data removal</button></section>`}
async function loadStoreTeam(){let el=document.querySelector('#teamMembers');if(!el)return;try{let {members}=await api('/api/team');el.innerHTML=members.map(m=>`<div class="activity"><span><b>${E(m.name)}</b> · ${E(m.email)}<br><small>${Object.entries(m.permissions).filter(([,v])=>v).map(([k])=>E(k)).join(' · ')}</small></span><button class="btn light small" onclick="removeStoreMember('${m.id}')">Remove access</button></div>`).join('')||'<p class="muted">No team members yet.</p>'}catch(e){el.textContent=e.message}}
