async function downloadAccountExport(){try{let r=await fetch('/api/account/export',{credentials:'same-origin'});if(!r.ok)throw Error((await r.json()).error||'Export failed');let a=document.createElement('a');a.href=URL.createObjectURL(await r.blob());a.download='yyc-account-export.json';a.click();URL.revokeObjectURL(a.href)}catch(e){toast(e.message)}}async function requestAccountRemoval(){let reason=prompt('Optional reason for your request');if(reason===null)return;try{await api('/api/account/deletion-request',{method:'POST',body:{reason}});await loadDeletionRequest();toast('Removal request sent for broker review')}catch(e){toast(e.message)}}async function cancelAccountRemoval(){try{await api('/api/account/deletion-request',{method:'DELETE',body:{}});await loadDeletionRequest()}catch(e){toast(e.message)}}async function loadDeletionRequest(){let el=document.querySelector('#deletionRequestState');if(!el)return;try{let {request}=await api('/api/account/deletion-request');if(request){el.innerHTML=`<p class="notice">Removal request ${E(request.status)} · ${E(new Date(request.requested_at).toLocaleDateString())} ${request.status==='pending'?'<button class="btn light small" onclick="cancelAccountRemoval()">Cancel request</button>':''}</p>`;let b=document.querySelector('#requestAccountRemoval');if(b)b.hidden=request.status==='pending'}}catch{}}
queueMicrotask(loadDeletionRequest);
const profileWithAccountStatus=realProfile;realProfile=function(){let html=profileWithAccountStatus();queueMicrotask(loadDeletionRequest);return html};
const caseOverviewWithServiceLevels=caseOverview;caseOverview=function(s){let html=caseOverviewWithServiceLevels(s),pickup=s.pickedUpAt?new Date(s.pickedUpAt).toLocaleString():'Not recorded',delivered=s.deliveredAt?new Date(s.deliveredAt).toLocaleString():'Not delivered';let pickupSla=s.pickupSlaMet==null?(s.promisedPickupAt&&Date.now()>Date.parse(s.promisedPickupAt)&&!s.pickedUpAt?'Pickup is late':'Awaiting pickup'):s.pickupSlaMet?'Met':'Late';let deliverySla=s.deliverySlaMet==null?(s.promisedDeliveryAt&&Date.now()>Date.parse(s.promisedDeliveryAt)&&s.status!=='Delivered'?'Delivery is late':'Awaiting delivery'):s.deliverySlaMet?'Met':'Late';return html+`<section class="card" style="margin-top:18px"><h2>Service-level timeline</h2><div class="review"><div><span>Promised pickup</span><b>${E(s.promisedPickupAt?new Date(s.promisedPickupAt).toLocaleString():'Not set')}</b></div><div><span>Actual pickup</span><b>${E(pickup)}</b></div><div><span>Pickup target</span><b>${E(pickupSla)}</b></div><div><span>Promised delivery by</span><b>${E(s.promisedDeliveryAt?new Date(s.promisedDeliveryAt).toLocaleString():'Not set')}</b></div><div><span>Actual delivery</span><b>${E(delivered)}</b></div><div><span>Delivery target</span><b>${E(deliverySla)}</b></div></div>${s.deliveryOutcome?`<p class="notice">Delivery outcome: ${E(s.deliveryOutcome)}${s.deliveryProof?.receivedQuantity!=null?' · quantity received '+E(s.deliveryProof.receivedQuantity):''}${s.deliveryProof?.shortage?' · shortage '+E(s.deliveryProof.shortage):''}${s.deliveryProof?.damage?' · damage '+E(s.deliveryProof.damage):''}</p>`:''}${s.claim?`<p class="notice">Claim ${E(s.claim.status)} · ${E(s.claim.type)}${s.claim.resolution?' · '+E(s.claim.resolution):''}</p>`:''}</section>`};
const docsWithPayoutDetail=caseDocuments;caseDocuments=function(s){let html=docsWithPayoutDetail(s),p=s.payoutBreakdown;if(role==='driver'&&p)html+=`<section class="card"><h2>Driver compensation</h2><div class="review"><div><span>Agreed rate</span><b>${money(p.baseAmount)}</b></div><div><span>Adjustment</span><b>${money(p.adjustment)}</b></div><div><span>Reason</span><b>${E(p.adjustmentReason||'No adjustment')}</b></div><div><span>Transfer total</span><b>${money(p.total)}</b></div><div><span>Transfer reference</span><b>${E(p.transferId)}</b></div></div></section>`;return html};
const caseWithSlaProofLinks=caseOverview;caseOverview=function(s){let html=caseWithSlaProofLinks(s),proofs=[['Pickup',s.pickupProof?.photoDocumentId],['Delivery',s.deliveryProof?.photoDocumentId],...(s.stopProgress||[]).map((x,i)=>[`Stop ${i+1}`,x.photoDocumentId])].filter(([,id])=>id);if(proofs.length)html+=`<section class="card" style="margin-top:18px"><h2>Delivery proof files</h2>${proofs.map(([label,id])=>`<button class="btn light small" style="margin:8px" onclick="openProofDocument('${id}')">View ${E(label)} proof</button>`).join('')}</section>`;return html};
async function openProofDocument(id){try{let {downloadUrl}=await api('/api/documents/'+id+'/download');window.open(downloadUrl,'_blank','noopener,noreferrer')}catch(e){toast(e.message)}}
const renderBeforeRequestedQuantity=render;render=function(){renderBeforeRequestedQuantity();if(page==='booking'&&bookingStep===2&&!document.querySelector('#requestedQuantity')){let goods=document.querySelector('#goods')?.closest('.field');if(goods){let field=document.createElement('div');field.className='field';field.innerHTML='<label for="requestedQuantity">Expected item quantity (optional)</label><input id="requestedQuantity" name="requestedQuantity" type="number" min="1" max="1000000" step="1" value="'+E(bookingData.requestedQuantity||'')+'"><small>Drivers record the quantity received and any shortages or refused items.</small>';goods.after(field)}}let foot=document.querySelector('.footnote');if(foot)foot.textContent='YYC Brokers · Server-backed delivery workspace · Provider-dependent features show their status in each workflow'};
const controlsWithTeamPermissions=controls;controls=function(s){if(role==='store'&&sessionUser?.team&&!sessionUser.team.isOwner&&!sessionUser.team.permissions['shipments.write'])return '<h2>Read-only team access</h2><p class="muted" style="margin-top:10px">Your team role can view this shipment. Ask the store owner for permission to make changes.</p>';return controlsWithTeamPermissions(s)};
const documentsWithTeamPermissions=caseDocuments;caseDocuments=function(s){if(role==='store'&&sessionUser?.team&&!sessionUser.team.isOwner&&!sessionUser.team.permissions['billing.read'])return `<section class="card"><h2>Shipment evidence</h2><p class="muted">Receipt ${E(s.pod||'not recorded')} · ${E(s.recipient||'')}</p></section>`;return documentsWithTeamPermissions(s)};
createDriverPayout=async function(id){let raw=prompt('Payout adjustment in CAD (use a negative amount for a deduction; leave blank for no adjustment)','0');if(raw===null)return;let adjustment=Number(raw||0),adjustmentReason=adjustment?prompt('Reason for this payout adjustment'):'';if(adjustment&&!adjustmentReason?.trim())return;try{await api('/api/admin/shipments/'+id+'/payout',{method:'POST',body:{adjustment,adjustmentReason}});await loadState();render();toast('Payout recorded with its breakdown')}catch(e){toast(e.message)}};

navs.admin.push(['accountRequests','user','Removal requests']);const contentBeforeRemovalQueue=content;content=function(){if(role==='admin'&&page==='accountRequests')return accountRemovalQueue();return contentBeforeRemovalQueue()};
function accountRemovalQueue(){queueMicrotask(loadAccountRemovalQueue);return title('Account data removal','Review requests and anonymize account identifiers after approval.')+`<section class="card"><div id="accountRemovalQueue">Loading requests…</div></section>`}
async function loadAccountRemovalQueue(){let el=document.querySelector('#accountRemovalQueue');if(!el)return;try{let {requests}=await api('/api/admin/account-deletion-requests');el.innerHTML=requests.map(r=>`<div class="activity"><span><b>${E(r.name)}</b> · ${E(r.email)} · ${E(r.role)}<br>${E(r.reason||'No reason provided')} · ${E(new Date(r.requested_at).toLocaleString())}</span><button class="btn" onclick="decideRemoval('${r.id}','approve')">Approve and anonymize</button><button class="btn light" onclick="decideRemoval('${r.id}','reject')">Reject</button></div>`).join('')||'No pending removal requests.'}catch(e){el.textContent=e.message}}async function decideRemoval(id,decision){let notes=prompt('Decision notes')||'';try{await api('/api/admin/account-deletion-requests/'+id,{method:'POST',body:{decision,notes}});await loadAccountRemovalQueue()}catch(e){toast(e.message)}}

/* Keep the one-time reset token out of the address bar and browser history once captured. */
if(resetToken)history.replaceState(null,'',location.pathname==='/reset-password'?'/':location.pathname);

/* Broker: take a driver off an offered/assigned job without discarding the quote. */
