const controlsBeforeUnassign=controls;controls=function(s){let html=controlsBeforeUnassign(s);if(role==='admin'&&['Offered','Assigned'].includes(s.status))html+=`<button class="btn light" style="margin-top:14px" onclick="unassignDriver('${s.id}')">Remove driver and return to dispatch</button>`;return html};

/* Driver: Stripe Connect payouts setup. */
async function startStripeConnect(){try{let {onboardingUrl}=await api('/api/payments/connect/onboard',{method:'POST',body:{}});location.href=onboardingUrl}catch(e){toast(e.message)}}
async function finishStripeConnect(){try{await api('/api/payments/connect/complete',{method:'POST',body:{}});await loadState();render();toast('Payouts connected. YYC can now pay you through Stripe.')}catch(e){toast(e.message)}}
const profileBeforePayouts=realProfile;realProfile=function(){let html=profileBeforePayouts();if(sessionUser?.role!=='driver')return html;return html+`<section class="card" style="margin-top:20px"><h2>Payouts</h2>${sessionUser.payoutsReady?'<p>Your Stripe account is connected. Delivery payouts are sent there.</p>':'<p class="muted">Connect a Stripe account so YYC can pay you for completed deliveries.</p><button class="btn" onclick="startStripeConnect()">Set up payouts with Stripe</button> <button class="btn light" onclick="finishStripeConnect()">I have finished Stripe setup</button>'}</section>`};
(function(){let st=new URLSearchParams(location.search).get('stripe');if(!st)return;history.replaceState(null,'',location.pathname);let tries=0,wait=setInterval(()=>{if(!sessionUser&&++tries<=40)return;clearInterval(wait);if(sessionUser?.role!=='driver')return;page='profile';if(st==='success')finishStripeConnect();else{render();toast('Stripe needs a few more details. Choose “Set up payouts with Stripe” to continue.')}},250)})();

/* Live updates: also refresh on payments, new requests and new open loads; reconnect after the
   server drops the socket (e.g. access changed) so only still-permitted rooms are rejoined. */
const connectLiveUpdatesBase=connectLiveUpdates;connectLiveUpdates=function(){let fresh=!liveSocket;connectLiveUpdatesBase();if(!fresh||!liveSocket)return;let refresh=async()=>{if(liveRefresh)return;liveRefresh=true;try{await loadState();render()}catch{}finally{liveRefresh=false}};for(let ev of ['payment:update','shipment:new','shipment:market'])liveSocket.on(ev,refresh);liveSocket.on('disconnect',reason=>{if(reason==='io server disconnect'&&sessionUser)setTimeout(()=>{if(sessionUser&&liveSocket&&!liveSocket.connected)liveSocket.connect()},2000)})};

/* Broker accounts must enrol an authenticator before the workspace loads. */
let mfaGate=false;
const loadStateBeforeMfaGate=loadState;loadState=async function(...args){try{let result=await loadStateBeforeMfaGate(...args);mfaGate=false;return result}catch(e){if(e.code!=='mfa_enrollment_required')throw e;let s=await api('/api/session');sessionUser=s.user;csrfToken=s.csrf||csrfToken;shipments=[];role=actualRole=sessionUser?.role||role;impersonating=false;mfaGate=true}};
const renderBeforeMfaGate=render;render=function(){if(mfaGate&&sessionUser){$('#root').innerHTML='<main class="authloading">'+logo()+'<h2>Set up two-step sign-in</h2><p>Broker accounts must use an authenticator app (Google Authenticator, Authy, 1Password…) before opening the workspace.</p><p><button class="btn" onclick="beginMfaEnrollment()">Set up authenticator</button> <button class="btn light" onclick="logoutAccount()">Log out</button></p></main>';return}renderBeforeMfaGate()};
finishMfaEnrollment=async function(e){e.preventDefault();try{let d=await api('/api/mfa/enroll/verify',{method:'POST',body:Object.fromEntries(new FormData(e.target))});alert('Save these backup codes securely: '+d.backupCodes.join(', '));closeDrawer();toast('Authenticator enabled');if(mfaGate){mfaGate=false;await loadState();page='dispatch';render()}}catch(x){toast(x.message)}};

/* Decline a store request with a reason the store can read. */
async function declineRequest(id,name,question){let reason=prompt(question);if(!reason?.trim())return;await action(id,name,{reason})}

/* Claim decisions: a credit needs an amount (refunded automatically if already paid). */
resolveShipmentClaim=async function(id){let decision=prompt('Decision: accepted, declined, credit, or replacement','accepted');if(!decision)return;decision=decision.trim().toLowerCase();let data={decision};if(decision==='credit'){let credit=prompt('Credit amount before GST (CAD)');if(!credit)return;data.creditAmount=Number(credit);if(!Number.isFinite(data.creditAmount)||data.creditAmount<=0){toast('Enter a positive credit amount');return}}data.resolution=prompt('Decision notes for the store');if(data.resolution?.trim())await action(id,'resolveClaim',data)};

/* Driver payouts: open claims block them; shortage/damage deliveries need explicit confirmation. */
createDriverPayout=async function(id){let s=shipments.find(x=>x.id===id),confirmPartial=false;if(s?.claim?.status==='open'){toast('Resolve the open delivery claim before paying the driver.');return}if(s?.deliveryOutcome==='partial_or_damaged'&&!s.claim){if(!confirm('This delivery recorded shortage, damage or refusal and no claim was opened. Pay the driver anyway?'))return;confirmPartial=true}let raw=prompt('Payout adjustment in CAD (use a negative amount for a deduction; leave blank for no adjustment)','0');if(raw===null)return;let adjustment=Number(raw||0),adjustmentReason=adjustment?prompt('Reason for this payout adjustment'):'';if(adjustment&&!adjustmentReason?.trim())return;try{await api('/api/admin/shipments/'+id+'/payout',{method:'POST',body:{adjustment,adjustmentReason,confirmPartial}});await loadState();render();toast('Payout recorded with its breakdown')}catch(e){toast(e.message)}};

/* Driver: update truck details (sends the truck back for broker approval). */
async function saveTruck(e){e.preventDefault();if(!confirm('Changing your truck needs broker re-approval, and jobs you have not picked up yet go back to dispatch. Continue?'))return;let d=Object.fromEntries(new FormData(e.target));d.kg=Number(d.kg);d.pallets=Number(d.pallets);d.liftgate=!!d.liftgate;try{let r=await api('/api/truck',{method:'PATCH',body:d});await loadState();render();toast(r.released.length?`Truck updated. ${r.released.length} job(s) returned to dispatch until re-approval.`:'Truck updated. Awaiting broker re-approval.')}catch(x){toast(x.message)}}
const profileBeforeTruck=realProfile;realProfile=function(){let html=profileBeforeTruck();if(sessionUser?.role!=='driver'||!sessionUser.truck)return html;let t=sessionUser.truck;return html+`<section class="card" style="margin-top:20px"><h2>My truck</h2><p class="muted">${t.approved?'Approved for dispatch.':'Awaiting broker approval.'}</p><form onsubmit="saveTruck(event)"><div class="grid2">${field('truck','Truck model','text','',t.truck||'')}${field('plate','Plate','text','',t.plate||'')}</div><div class="grid2"><div class="field"><label for="truckType">Truck type</label><select id="truckType" name="type">${['Box truck','Dry van'].map(x=>`<option ${x===t.type?'selected':''}>${x}</option>`).join('')}</select></div>${field('area','Service area','text','',t.area||'')}</div><div class="grid2">${field('kg','Payload (kg)','number','',String(t.kg||''))}${field('pallets','Pallet capacity','number','',String(t.pallets||''))}</div><label><input type="checkbox" name="liftgate" ${t.liftgate?'checked':''}> Liftgate</label><button class="btn light" style="margin-top:12px">Save truck changes</button></form></section>`};

/* Duplicate a request: keep stop fields in their positions (empty contact stays empty) and
   copy every booking detail except the date. */
duplicateShipment=function(id){let s=shipments.find(x=>x.id===id);if(!s)return;bookingData={pickup:s.pickup,destination:s.destination,date:'',window:s.window,goods:s.goods,pallets:s.pallets,kg:s.kg,type:s.type,unloading:s.unloading,notes:s.notes||'',pickupContact:s.pickupContact||'',receivingContact:s.receivingContact||'',hours:s.hours||'',appointment:s.appointment||'',cargoNotes:s.cargoNotes||'',requestedQuantity:s.requestedQuantity??'',pickupServiceMinutes:s.pickupServiceMinutes??30,deliveryServiceMinutes:s.deliveryServiceMinutes??30,stops:(s.stops||[]).map(x=>typeof x==='string'?x:[x.address||'',x.contact||'',x.window||'',x.serviceMinutes??''].map(v=>String(v).replace(/\|/g,'\\|')).join(' | ')).join('\n')};bookingStep=1;page='booking';render();toast('Review the copied request and choose a new date')};

/* Browser location sharing: keep trying through dead zones; stop only when the server says
   the delivery is no longer in transit, or when the delivery finishes. */
startBrowserTracking=function(shipmentId){if(!navigator.geolocation){toast('This browser does not support location');return}if(gpsWatches.has(shipmentId)){navigator.geolocation.clearWatch(gpsWatches.get(shipmentId));gpsWatches.delete(shipmentId);toast('Location sharing stopped');return}let failing=false;const stop=message=>{navigator.geolocation.clearWatch(watch);gpsWatches.delete(shipmentId);if(message)toast(message)};const watch=navigator.geolocation.watchPosition(async pos=>{try{await api('/api/gps/location',{method:'POST',body:{shipmentId,latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy,speed:pos.coords.speed,heading:pos.coords.heading,altitude:pos.coords.altitude}});if(failing){failing=false;toast('Location sharing reconnected')}}catch(e){if([400,401,403,404].includes(e.status))stop('Location sharing stopped: '+e.message);else if(!failing){failing=true;toast('Connection lost. Location sharing will resume automatically.')}}},e=>toast(e.message),{enableHighAccuracy:true,maximumAge:15000,timeout:20000});gpsWatches.set(shipmentId,watch);toast('Sharing location while this page stays open')};
const loadStateBeforeGpsStop=loadState;loadState=async function(...args){let result=await loadStateBeforeGpsStop(...args);for(let [id,watch] of gpsWatches){let s=shipments.find(x=>x.id===id);if(!s||s.status!=='In transit'){navigator.geolocation.clearWatch(watch);gpsWatches.delete(id);toast(`Location sharing for ${id} ended`)}}return result};

/* Cancellation requests (store) and mid-delivery recovery (broker). */
async function requestCancellation(id){let reason=prompt('Why should YYC cancel this delivery?');if(reason?.trim())await action(id,'requestCancellation',{reason})}
unassignDriver=async function(id){let s=shipments.find(x=>x.id===id),data={};data.reason=prompt('Why is this driver being removed? (saved in the audit record)');if(!data.reason?.trim())return;if(s?.status==='In transit'){data.handoffLocation=prompt('Where are the goods now? This becomes the pickup address for the next driver.');if(!data.handoffLocation?.trim())return}await action(id,'unassignDriver',data)};
const controlsBeforeCancellation=controls;controls=function(s){let html=controlsBeforeCancellation(s);if(s.pickupDatePassedAt&&['Awaiting quote','Quote ready','Ready to assign','Offered'].includes(s.status))html=`<div class="alertbadge">Pickup date ${E(s.date)} has passed. ${role==='store'?'Request a new delivery time to continue.':'Waiting for the store to request a new date.'}</div>`+html;if(role==='store'&&['Ready to assign','Offered','Assigned'].includes(s.status))html+=s.cancellationRequest?.status==='open'?`<p class="notice">Cancellation requested: ${E(s.cancellationRequest.reason)}</p><button class="btn light" style="margin-top:12px" onclick="action('${s.id}','withdrawCancellation',{})">Withdraw cancellation request</button>`:`<button class="btn light" style="margin-top:12px" onclick="requestCancellation('${s.id}')">Request cancellation</button>`;if(role==='admin'&&s.cancellationRequest?.status==='open'&&!['Delivered','Cancelled'].includes(s.status))html+=`<div class="notice">Store asked to cancel: ${E(s.cancellationRequest.reason)}</div><button class="btn light" onclick="declineRequest('${s.id}','declineCancellation','Why is the cancellation declined?')">Decline cancellation</button>`;if(role==='admin'&&s.status==='In transit')html+=`<button class="btn light" style="margin-top:14px" onclick="unassignDriver('${s.id}')">Breakdown: hand the load to another driver</button>`;return html};

/* Verification screen: request a new code, or go back to sign in. */
async function resendVerificationCode(){let email=document.querySelector('#realAuth input[name=email]')?.value||document.querySelector('#email')?.value||'';if(!email){$('#authError').textContent='Enter your account email first.';return}try{let r=await api('/api/resend-code',{method:'POST',body:{email}});toast(r.message)}catch(x){$('#authError').textContent=x.message}}
const authBeforeResend=auth;auth=function(){authBeforeResend();if(authFlow!=='verify')return;let form=document.querySelector('#realAuth');if(!form||form.parentElement.querySelector('.verifyextras'))return;let extras=document.createElement('div');extras.className='row between wrap verifyextras';extras.style.marginTop='12px';extras.innerHTML='<button class="textbtn" type="button" onclick="resendVerificationCode()">Send a new code</button><button class="textbtn" type="button" onclick="authFlow=\'login\';auth()">Back to login</button>';form.after(extras)};

/* Broker change form: the pickup date and window can be changed too (e.g. after the date passed). */
const editShipmentBeforeDate=editShipment;editShipment=function(id){editShipmentBeforeDate(id);let s=shipments.find(x=>x.id===id),form=$('#overlay form'),submit=form?.querySelector('button.btn');if(!s||!form||form.elements.date)return;let box=document.createElement('div');box.className='grid2';box.innerHTML=`<div class="field"><label for="changeDate">Pickup date</label><input id="changeDate" type="date" name="date" value="${E(s.date||'')}"></div><div class="field"><label for="changeWindow">Pickup window</label><select id="changeWindow" name="window">${['09:00–12:00','13:00–16:00','Flexible'].map(w=>`<option ${w===s.window?'selected':''}>${w}</option>`).join('')}</select></div>`;(submit||form.lastElementChild).before(box)};

/* Mid-delivery hand-off records the departing driver's pay for their leg. */
unassignDriver=async function(id){let s=shipments.find(x=>x.id===id),data={};data.reason=prompt('Why is this driver being removed? (saved in the audit record)');if(!data.reason?.trim())return;if(s?.status==='In transit'){data.handoffLocation=prompt('Where are the goods now? This becomes the pickup address for the next driver.');if(!data.handoffLocation?.trim())return;let pay=prompt(`Pay for the departing driver's leg in CAD (agreed rate ${money(s.rate)}; enter 0 for none). Paid with the final payout.`,'0');if(pay===null)return;data.handoffPay=Number(pay||0);if(!Number.isFinite(data.handoffPay)||data.handoffPay<0){toast('Enter zero or a positive amount');return}}await action(id,'unassignDriver',data)};

/* Broker: retry failed claim refunds and hand-off payouts. */
async function retryShipmentPayments(id){try{let r=await api('/api/admin/shipments/'+id+'/retry-payments',{method:'POST',body:{}});await loadState();render();let failed=[...r.credits.filter(c=>c.refund==='failed'),...r.handoffs.filter(h=>h.payout==='failed')];toast(failed.length?`${failed.length} payment(s) still failing: ${failed.map(x=>x.refundError||x.payoutError).join('; ')}`:'Payments retried successfully')}catch(e){toast(e.message)}}
const controlsBeforeRetry=controls;controls=function(s){let html=controlsBeforeRetry(s);if(role!=='admin')return html;let failedCredits=(s.credits||[]).filter(c=>c.refund==='failed'),dueHandoffs=(s.handoffs||[]).filter(h=>['due','failed'].includes(h.payout));if(dueHandoffs.length)html+=`<div class="notice">Hand-off pay owed: ${dueHandoffs.map(h=>`${money(h.payAmount)} (${E(h.payout)}${h.payoutError?': '+E(h.payoutError):''})`).join(', ')}. Paid together with the driver payout.</div>`;if(failedCredits.length||(s.payoutStatus==='paid'&&dueHandoffs.some(h=>h.payout==='failed')))html+=`<button class="btn light" style="margin-top:12px" onclick="retryShipmentPayments('${s.id}')">Retry failed refunds / payouts</button>`;return html};

/* Broker work queue: every shipment waiting on a broker decision, with the reason. */
function brokerQueueReasons(s){let r=[];if(s.issue&&!s.issue.resolved)r.push('Open exception');if(s.claim?.status==='open')r.push('Open claim');if(s.cancellationRequest?.status==='open'&&!['Delivered','Cancelled'].includes(s.status))r.push('Cancellation request');if(s.rescheduleRequest?.status==='open'&&!['Delivered','Cancelled','In transit'].includes(s.status))r.push('Reschedule request');if(s.quoteRevisionRequest?.status==='open'&&s.status==='Quote ready')r.push('Quote revision request');if(s.pickupDatePassedAt&&['Awaiting quote','Quote ready','Ready to assign','Offered'].includes(s.status))r.push('New date needed');if((s.credits||[]).some(c=>c.refund==='failed')||(s.handoffs||[]).some(h=>h.payout==='failed')||s.overpaymentRefund?.status==='failed'||(s.overpaymentRefunds||[]).some(x=>x.status==='failed'))r.push('Payment failed');let disputeOpen=s.dispute&&!['won','lost','warning_closed'].includes(s.dispute.status);if(disputeOpen)r.push('Card dispute'+(s.dispute.dueBy?' · respond by '+new Date(s.dispute.dueBy).toLocaleDateString('en-CA'):''));if(s.status==='Delivered'&&paymentSettled(s)&&s.payoutStatus!=='paid'&&!disputeOpen)r.push('Driver payout due');if(dispatchExpired(s))r.push(s.status==='Offered'?'Offer expired':'Quote expired');if(s.status==='Awaiting quote'&&!s.pickupDatePassedAt)r.push('Quote needed');if(s.status==='Ready to assign'&&!s.pickupDatePassedAt)r.push((s.bids||[]).length?`${s.bids.length} bid(s) to review`:'Ready to assign');return r}
realAlerts=function(){let list=shipments.map(s=>[s,brokerQueueReasons(s)]).filter(([,r])=>r.length);let rank=r=>r.some(x=>x.startsWith('Card dispute'))||['Open exception','Payment failed','Open claim','Cancellation request','New date needed'].some(x=>r.includes(x))?0:1;list.sort((a,b)=>rank(a[1])-rank(b[1])||String(a[0].date||'').localeCompare(String(b[0].date||'')));return title('Operations work queue','Every delivery waiting on a broker decision.')+(shipmentNextCursor?'<p class="notice">Showing loaded deliveries only. Load more shipments to include older records.</p>':'')+`<div class="grid2">${list.length?list.map(([s,r])=>`<section class="card"><div class="row wrap" style="gap:6px">${r.map(x=>`<span class="tag amber">${E(x.toUpperCase())}</span>`).join('')}</div><h2 style="margin-top:15px">${s.id} · ${E(s.customer)}</h2><p class="muted" style="margin:15px 0">${E(s.issue&&!s.issue.resolved?s.issue.reason:s.destination)} · ${E(s.date||'')}</p>${dispatchExpired(s)?`<button class="btn light" onclick="action('${s.id}','${s.status==='Offered'?'expireOffer':'expireQuote'}')">Close expired ${s.status==='Offered'?'offer':'quote'}</button> `:''}<button class="btn light" onclick="openDelivery('${s.id}')">Review delivery →</button></section>`).join(''):'<div class="card empty full">No shipment actions waiting.</div>'}</div>`};

/* Reports: include final-delivery on-time results and say when data is partial. */
const operationsReportBase=operationsReport;operationsReport=function(){let html=operationsReportBase(),done=shipments.filter(s=>s.status==='Delivered'&&typeof s.deliverySlaMet==='boolean'),onTime=done.filter(s=>s.deliverySlaMet).length,extra=`<section class="card" style="margin-top:20px"><h2>Final delivery on time</h2><p style="margin-top:10px">${done.length?`${Math.round(100*onTime/done.length)}% (${onTime} of ${done.length} deliveries with a promised time)`:'No delivered shipments with a promised delivery time yet.'}</p></section>`;return (shipmentNextCursor?'<p class="notice">Based on the shipments loaded so far. Load more shipments for a complete report.</p>':'')+html+extra};

/* A delivery is settled when paid, or refunded only because credits cover the whole price. */
function paymentSettled(s){let credits=(s.credits||[]).reduce((sum,c)=>sum+Math.round(Number(c.amount||0)*100),0);return s.paymentStatus==='succeeded'||(s.paymentStatus==='refunded'&&Math.round(Number(s.price||0)*100)-credits<=0)}

/* Change password while signed in (other devices are signed out). */
async function changePassword(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.newPassword!==d.confirmPassword){toast('New passwords do not match');return}try{let r=await api('/api/account/password',{method:'POST',body:{currentPassword:d.currentPassword,newPassword:d.newPassword}});csrfToken=r.csrf;e.target.reset();toast(r.message)}catch(x){toast(x.message)}}
const profileBeforePassword=realProfile;realProfile=function(){return profileBeforePassword()+`<section class="card" style="margin-top:20px"><h2>Change password</h2><form onsubmit="changePassword(event)"><div class="field"><label for="currentPassword">Current password</label><input id="currentPassword" name="currentPassword" type="password" autocomplete="current-password" required></div><div class="grid2"><div class="field"><label for="newPassword">New password</label><input id="newPassword" name="newPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div><div class="field"><label for="confirmPassword">Confirm new password</label><input id="confirmPassword" name="confirmPassword" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></div></div><button class="btn light">Change password</button><p class="muted" style="margin-top:8px">Other devices will be signed out.</p></form></section>`};

/* Store team members can leave the team they were added to. */
async function leaveStoreTeam(){if(!confirm('Leave this store team? You will lose access to its shipments.'))return;try{await api('/api/team/membership',{method:'DELETE',body:{}});await loadState();render();toast('You left the store team')}catch(e){toast(e.message)}}
const profileBeforeLeaveTeam=realProfile;realProfile=function(){let html=profileBeforeLeaveTeam();if(sessionUser?.role==='store'&&sessionUser.team&&!sessionUser.team.isOwner)html+=`<section class="card" style="margin-top:20px"><h2>Store team</h2><p class="muted">You have access to another store's shipments as a team member.</p><button class="btn light" style="margin-top:12px" onclick="leaveStoreTeam()">Leave this team</button></section>`;return html};

/* Broker admin page: who uploaded each document (with a View button), documents expiring soon,
   and searchable, paged accounts with verification and MFA help. */
let accountQuery='',accountOffset=0;
loadAdminAccounts=async function(){let el=document.querySelector('#adminAccounts'),docs=document.querySelector('#pendingDocuments');if(!el&&!docs)return;try{let [a,d,x]=await Promise.all([api('/api/admin/accounts?q='+encodeURIComponent(accountQuery)+'&offset='+accountOffset),api('/api/admin/documents/pending'),api('/api/admin/documents/expiring')]);
if(docs)docs.innerHTML=d.documents.map(doc=>`<div class="activity"><span><b>${E(doc.user_name||'Unknown')}</b> (${E(doc.user_email||'')}) · ${E(doc.type)} · ${E(doc.filename)} · expires ${E(doc.expiry_date?String(doc.expiry_date).slice(0,10):'not set')}</span><button class="btn light small" onclick="openProofDocument('${doc.id}')">View</button><button class="btn light small" onclick="reviewDocument('${doc.id}','approve')">Approve</button><button class="btn light small" onclick="reviewDocument('${doc.id}','reject')">Reject</button></div>`).join('')||'No pending uploads';
let expiring=document.querySelector('#expiringDocuments');if(!expiring&&docs){let card=document.createElement('section');card.className='card';card.style.marginTop='22px';card.innerHTML='<h2>Documents expiring in 30 days</h2><div id="expiringDocuments"></div>';docs.closest('section')?.after(card);expiring=card.querySelector('#expiringDocuments')}if(expiring)expiring.innerHTML=x.documents.map(doc=>`<div class="activity"><span><b>${E(doc.user_name)}</b> · ${E(doc.type)} · expires ${E(String(doc.expiry_date).slice(0,10))}</span><button class="btn light small" onclick="openProofDocument('${doc.id}')">View</button></div>`).join('')||'Nothing expiring in the next 30 days.';
if(el)el.innerHTML=`<form class="row wrap" style="gap:8px;margin-bottom:12px" onsubmit="event.preventDefault();accountQuery=this.q.value;accountOffset=0;loadAdminAccounts()"><input name="q" placeholder="Search name or email" value="${E(accountQuery)}" style="flex:1;min-width:200px"><button class="btn light small">Search</button></form>`+(a.accounts.map(acc=>`<div class="activity"><span><b>${E(acc.name)}</b> · ${E(acc.email)} · ${E(acc.role)} · ${acc.email_verified?'Verified':'Unverified'} · ${acc.disabled?'Suspended':'Active'}${acc.mfa_enabled?' · MFA':''}</span>${acc.id!==sessionUser.id?`<button class="btn light small" onclick="changeAccount('${acc.id}',${acc.disabled?'false':'true'})">${acc.disabled?'Restore':'Suspend'}</button>`:''}${!acc.email_verified&&!acc.disabled?`<button class="btn light small" onclick="accountHelp('${acc.id}','resend-verification')">Resend code</button><button class="btn light small" onclick="accountHelp('${acc.id}','verify-email','Confirm this email without a code? Only do this after checking who the person is.')">Mark verified</button>`:''}${acc.mfa_enabled&&acc.id!==sessionUser.id&&!acc.disabled?`<button class="btn light small" onclick="accountHelp('${acc.id}','reset-mfa','Reset two-step sign-in for this account? Only do this after confirming who the person is.')">Reset MFA</button>`:''}</div>`).join('')||'No matching accounts.')+`<div class="row" style="gap:8px;margin-top:12px">${accountOffset?'<button class="btn light small" onclick="accountOffset=Math.max(0,accountOffset-50);loadAdminAccounts()">← Newer</button>':''}${a.nextOffset!=null?`<button class="btn light small" onclick="accountOffset=${a.nextOffset};loadAdminAccounts()">Older →</button>`:''}</div>`}catch(e){if(el)el.textContent=e.message}};
async function accountHelp(id,operation,question){if(question&&!confirm(question))return;try{let r=await api(`/api/admin/accounts/${id}/${operation}`,{method:'POST',body:{}});toast(r.message);await loadAdminAccounts()}catch(e){toast(e.message)}}

/* Backup codes: shown on screen with copy, and kept until the user confirms they saved them. */
function showBackupCodes(codes){$('#overlay').innerHTML=`<section class="card"><h2>Save your backup codes</h2><p>Each code works once if you lose your authenticator. Store them somewhere safe; they will not be shown again.</p><pre style="font-size:16px;line-height:1.6;user-select:all">${codes.map(E).join('\n')}</pre><button class="btn light" onclick="navigator.clipboard?.writeText(${E(JSON.stringify(codes.join('\n')))}).then(()=>toast('Codes copied'))">Copy codes</button><label style="display:block;margin:12px 0"><input type="checkbox" onchange="document.getElementById('backupDone').disabled=!this.checked"> I have saved these codes</label><button id="backupDone" class="btn" disabled onclick="closeDrawer()">Done</button></section>`}
finishMfaEnrollment=async function(e){e.preventDefault();try{let d=await api('/api/mfa/enroll/verify',{method:'POST',body:Object.fromEntries(new FormData(e.target))});toast('Authenticator enabled');if(mfaGate){mfaGate=false;await loadState();page='dispatch';render()}showBackupCodes(d.backupCodes)}catch(x){toast(x.message)}};

/* Profile: two-step sign-in management. */
async function loadMfaPanel(){let el=document.querySelector('#mfaPanel');if(!el)return;try{let st=await api('/api/mfa/status');el.innerHTML=st.mfaEnabled?`<p>Two-step sign-in is on. ${st.remainingBackupCodes} backup code(s) left.</p><form class="row wrap" style="gap:8px;margin-top:10px" onsubmit="regenerateBackupCodes(event)"><input name="code" inputmode="numeric" placeholder="Authenticator code" required><button class="btn light small">New backup codes</button></form>${st.mfaEnforced?'<p class="muted" style="margin-top:8px">Broker accounts must keep two-step sign-in.</p>':`<form class="row wrap" style="gap:8px;margin-top:10px" onsubmit="disableMfa(event)"><input name="code" inputmode="numeric" placeholder="Authenticator or backup code" required><input name="password" type="password" placeholder="Password" required><button class="btn light small">Turn off</button></form>`}`:'<p>Two-step sign-in is off.</p><button class="btn light small" style="margin-top:10px" onclick="beginMfaEnrollment()">Set up authenticator</button>'}catch(e){el.textContent=e.message}}
async function regenerateBackupCodes(e){e.preventDefault();try{let d=await api('/api/mfa/backup-codes/regenerate',{method:'POST',body:Object.fromEntries(new FormData(e.target))});showBackupCodes(d.backupCodes);loadMfaPanel()}catch(x){toast(x.message)}}
async function disableMfa(e){e.preventDefault();if(!confirm('Turn off two-step sign-in?'))return;try{await api('/api/mfa/disable',{method:'POST',body:Object.fromEntries(new FormData(e.target))});toast('Two-step sign-in turned off');loadMfaPanel()}catch(x){toast(x.message)}}
const profileBeforeMfa=realProfile;realProfile=function(){queueMicrotask(loadMfaPanel);return profileBeforeMfa()+'<section class="card" style="margin-top:20px"><h2>Two-step sign-in</h2><div id="mfaPanel">Loading…</div></section>'};
